INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'linear',
  'Simple Linear Layer',
  'Medium',
  '基础层',
  'SimpleLinear',
  '# 🟡 Medium: Simple Linear Layer

Implement a fully-connected linear layer: **y = xW^T + b**

### Signature
```python
class SimpleLinear:
    def __init__(self, in_features: int, out_features: int): ...
    def forward(self, x: torch.Tensor) -> torch.Tensor: ...
```

### Requirements
- `self.weight`: shape `(out_features, in_features)`, init with `randn * (1/√in_features)`
- `self.bias`: shape `(out_features,)`, init as zeros
- Both must have `requires_grad=True`
- `forward(x)` computes `x @ W^T + b`
- Do **NOT** use `torch.nn.Linear`',
  'class SimpleLinear:',
  '',
  'y = x @ W^T + b. Initialize weight with Kaiming scaling: randn * (1/sqrt(in_features)).',
  '# ✏️ YOUR IMPLEMENTATION HERE

class SimpleLinear:
    def __init__(self, in_features: int, out_features: int):
        pass  # Initialize weight and bias

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        pass  # Compute y = x @ W^T + b',
  '[{"name": "Weight & bias shape", "code": "\nimport torch\nlayer = {fn}(8, 4)\nassert layer.weight.shape == (4, 8), f''Weight shape: {layer.weight.shape}''\nassert layer.bias.shape == (4,), f''Bias shape: {layer.bias.shape}''\nassert layer.weight.requires_grad, ''weight must require grad''\nassert layer.bias.requires_grad, ''bias must require grad''\n"}, {"name": "Forward pass", "code": "\nimport torch\nlayer = {fn}(8, 4)\nx = torch.randn(2, 8)\ny = layer.forward(x)\nassert y.shape == (2, 4), f''Output shape: {y.shape}''\nexpected = x @ layer.weight.T + layer.bias\nassert torch.allclose(y, expected, atol=1e-5), ''Forward != x @ W^T + b''\n"}, {"name": "Gradient flow", "code": "\nimport torch\nlayer = {fn}(8, 4)\nx = torch.randn(2, 8)\ny = layer.forward(x)\ny.sum().backward()\nassert layer.weight.grad is not None, ''weight.grad is None''\nassert layer.bias.grad is not None, ''bias.grad is None''\n"}]',
  '# ✅ SOLUTION

class SimpleLinear:
    def __init__(self, in_features: int, out_features: int):
        self.weight = torch.randn(out_features, in_features) * (1 / math.sqrt(in_features))
        self.weight.requires_grad_(True)
        self.bias = torch.zeros(out_features, requires_grad=True)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return x @ self.weight.T + self.bias',
  '# 🟡 Solution: Simple Linear Layer

Reference solution for a fully-connected linear layer: **y = xW^T + b**',
  'approved',
  5
)
