INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'causal_attention',
  'Causal Self-Attention',
  'Hard',
  '注意力机制',
  'causal_attention',
  '# 🔴 Hard: Causal Self-Attention

Implement **causal (masked) self-attention** — the attention used in GPT-style decoders.

Same as softmax attention, but each position can **only attend to itself and earlier positions** (no peeking at future tokens).

$$\text{scores}_{ij} = \begin{cases} \frac{Q_i \cdot K_j}{\sqrt{d_k}} & \text{if } j \le i \\ -\infty & \text{if } j > i \end{cases}$$

### Signature
```python
def causal_attention(Q, K, V):
    # Q, K, V: (batch, seq, d) → output: (batch, seq, d_v)
```

### Rules
- Do **NOT** use `F.scaled_dot_product_attention`
- Position $i$ can only attend to positions $\le i$
- You **may** use `torch.softmax`, `torch.bmm`, `torch.triu`',
  'def causal_attention(Q, K, V):',
  '',
  'Same as softmax attention but mask future positions with -inf before softmax. torch.triu(..., diagonal=1) gives the upper triangle.',
  '# ✏️ YOUR IMPLEMENTATION HERE

def causal_attention(Q, K, V):
    pass  # Replace this',
  '[{"name": "Output shape", "code": "\nimport torch\nout = {fn}(torch.randn(2, 6, 16), torch.randn(2, 6, 16), torch.randn(2, 6, 16))\nassert out.shape == (2, 6, 16), f''Shape mismatch: {out.shape}''\n"}, {"name": "Future tokens don''t affect past", "code": "\nimport torch\ntorch.manual_seed(0)\nB, S, D = 1, 8, 16\nQ = torch.randn(B, S, D)\nK = torch.randn(B, S, D)\nV = torch.randn(B, S, D)\nout1 = {fn}(Q, K, V)\nK2, V2 = K.clone(), V.clone()\nK2[:, 4:] = torch.randn(B, 4, D)\nV2[:, 4:] = torch.randn(B, 4, D)\nout2 = {fn}(Q, K2, V2)\nassert torch.allclose(out1[:, :4], out2[:, :4], atol=1e-5), ''Changing future K/V affected past outputs''\n"}, {"name": "First position only sees itself", "code": "\nimport torch\ntorch.manual_seed(0)\nQ = torch.randn(1, 4, 8)\nK = torch.randn(1, 4, 8)\nV = torch.randn(1, 4, 8)\nout = {fn}(Q, K, V)\nassert torch.allclose(out[:, 0], V[:, 0], atol=1e-5), ''Position 0 should output V[0]''\n"}, {"name": "Gradient flow", "code": "\nimport torch\nQ = torch.randn(2, 4, 8, requires_grad=True)\nK = torch.randn(2, 4, 8, requires_grad=True)\nV = torch.randn(2, 4, 8, requires_grad=True)\nout = {fn}(Q, K, V)\nout.sum().backward()\nassert Q.grad is not None and K.grad is not None and V.grad is not None, ''Missing gradients''\n"}]',
  '# ✅ SOLUTION

def causal_attention(Q, K, V):
    d_k = K.size(-1)
    scores = torch.bmm(Q, K.transpose(1, 2)) / math.sqrt(d_k)
    S = scores.size(-1)
    mask = torch.triu(torch.ones(S, S, device=scores.device, dtype=torch.bool), diagonal=1)
    scores = scores.masked_fill(mask.unsqueeze(0), float(''-inf''))
    weights = torch.softmax(scores, dim=-1)
    return torch.bmm(weights, V)',
  '# 🔴 Solution: Causal Self-Attention

Reference solution — softmax attention with an upper-triangular mask.',
  'approved',
  8
)
