INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'gqa',
  'Grouped Query Attention',
  'Hard',
  '注意力机制',
  'GroupQueryAttention',
  '# 🔴 Hard: Grouped Query Attention (GQA)

Implement **Grouped Query Attention** — used in LLaMA 2, Mistral, etc. to reduce KV cache size.

Like MHA, but with **fewer KV heads** than Q heads. Each group of Q heads shares the same K/V head.

### Signature
```python
class GroupQueryAttention:
    def __init__(self, d_model: int, num_heads: int, num_kv_heads: int): ...
    def forward(self, x) -> torch.Tensor:  # self-attention
```

### Requirements
- `self.W_q`: `nn.Linear(d_model, d_model)` — full Q projection
- `self.W_k`: `nn.Linear(d_model, num_kv_heads * d_k)` — reduced K projection
- `self.W_v`: `nn.Linear(d_model, num_kv_heads * d_k)` — reduced V projection
- `self.W_o`: `nn.Linear(d_model, d_model)` — output projection
- `d_k = d_model // num_heads`
- Expand KV heads with `repeat_interleave` to match Q heads
- When `num_kv_heads == num_heads`, should behave like standard MHA',
  'class GroupQueryAttention:',
  '',
  'Like MHA but fewer KV heads. W_k/W_v project to num_kv_heads * d_k dims. Use repeat_interleave to expand KV heads to match Q heads.',
  '# ✏️ YOUR IMPLEMENTATION HERE

class GroupQueryAttention:
    def __init__(self, d_model, num_heads, num_kv_heads):
        pass  # Initialize projections

    def forward(self, x):
        pass  # Self-attention with grouped KV',
  '[{"name": "Output shape", "code": "\nimport torch\ntorch.manual_seed(0)\ngqa = {fn}(d_model=32, num_heads=8, num_kv_heads=2)\nout = gqa.forward(torch.randn(2, 6, 32))\nassert out.shape == (2, 6, 32), f''Shape mismatch: {out.shape}''\n"}, {"name": "nn.Linear with correct shapes", "code": "\nimport torch, torch.nn as nn\ngqa = {fn}(d_model=32, num_heads=8, num_kv_heads=2)\nd_k = 32 // 8\nassert isinstance(gqa.W_q, nn.Linear) and gqa.W_q.weight.shape == (32, 32), f''W_q wrong''\nassert isinstance(gqa.W_k, nn.Linear) and gqa.W_k.weight.shape == (2 * d_k, 32), f''W_k shape: {gqa.W_k.weight.shape}''\nassert isinstance(gqa.W_v, nn.Linear) and gqa.W_v.weight.shape == (2 * d_k, 32), f''W_v shape: {gqa.W_v.weight.shape}''\nassert isinstance(gqa.W_o, nn.Linear), ''W_o should be nn.Linear''\n"}, {"name": "Degenerates to MHA when kv_heads == heads", "code": "\nimport torch\ntorch.manual_seed(42)\ngqa = {fn}(d_model=16, num_heads=4, num_kv_heads=4)\nout = gqa.forward(torch.randn(1, 4, 16))\nassert out.shape == (1, 4, 16)\nassert gqa.W_k.weight.shape == (16, 16), ''Full KV when kv_heads == heads''\n"}, {"name": "KV heads are shared correctly", "code": "\nimport torch\ntorch.manual_seed(0)\nD, H, KV = 16, 4, 2\nd_k = D // H\ngqa = {fn}(d_model=D, num_heads=H, num_kv_heads=KV)\nx = torch.randn(1, 4, D)\nk = gqa.W_k(x).view(1, 4, KV, d_k).transpose(1, 2)\nk_exp = k.repeat_interleave(H // KV, dim=1)\nassert torch.equal(k_exp[:, 0], k_exp[:, 1]), ''Heads 0,1 should share same K''\nassert not torch.equal(k_exp[:, 0], k_exp[:, 2]), ''Different groups need different K''\n"}, {"name": "Gradient flow", "code": "\nimport torch\ntorch.manual_seed(0)\ngqa = {fn}(d_model=16, num_heads=4, num_kv_heads=2)\nx = torch.randn(1, 4, 16, requires_grad=True)\ngqa.forward(x).sum().backward()\nassert x.grad is not None, ''x.grad is None''\nassert gqa.W_q.weight.grad is not None and gqa.W_k.weight.grad is not None, ''Missing weight gradients''\n"}]',
  '# ✅ SOLUTION

class GroupQueryAttention:
    def __init__(self, d_model, num_heads, num_kv_heads):
        self.num_heads = num_heads
        self.num_kv_heads = num_kv_heads
        self.d_k = d_model // num_heads
        self.W_q = nn.Linear(d_model, d_model)
        self.W_k = nn.Linear(d_model, num_kv_heads * self.d_k)
        self.W_v = nn.Linear(d_model, num_kv_heads * self.d_k)
        self.W_o = nn.Linear(d_model, d_model)

    def forward(self, x):
        B, S, _ = x.shape
        q = self.W_q(x).view(B, S, self.num_heads, self.d_k).transpose(1, 2)
        k = self.W_k(x).view(B, S, self.num_kv_heads, self.d_k).transpose(1, 2)
        v = self.W_v(x).view(B, S, self.num_kv_heads, self.d_k).transpose(1, 2)
        repeats = self.num_heads // self.num_kv_heads
        k = k.repeat_interleave(repeats, dim=1)
        v = v.repeat_interleave(repeats, dim=1)
        scores = torch.matmul(q, k.transpose(-2, -1)) / math.sqrt(self.d_k)
        weights = torch.softmax(scores, dim=-1)
        attn = torch.matmul(weights, v)
        out = attn.transpose(1, 2).contiguous().view(B, S, -1)
        return self.W_o(out)',
  '# 🔴 Solution: Grouped Query Attention

Reference solution for GQA — MHA with shared KV heads.',
  'approved',
  9
)
