INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'mha',
  'Multi-Head Attention',
  'Hard',
  '注意力机制',
  'MultiHeadAttention',
  '# 🔴 Hard: Multi-Head Attention

Implement **Multi-Head Attention** from scratch — the core building block of the Transformer.

$$\text{MultiHead}(Q, K, V) = \text{Concat}(\text{head}_1, \dots, \text{head}_h) W^O$$
$$\text{head}_i = \text{Attention}(Q W_i^Q,\; K W_i^K,\; V W_i^V)$$

### Signature
```python
class MultiHeadAttention:
    def __init__(self, d_model: int, num_heads: int): ...
    def forward(self, Q, K, V) -> torch.Tensor: ...
```

### Requirements
- Use `nn.Linear(d_model, d_model)` for `self.W_q`, `self.W_k`, `self.W_v`, `self.W_o`
- `d_k = d_model // num_heads` per head
- `forward(Q, K, V)`: Q is `(B, seq_q, d_model)`, K/V are `(B, seq_k, d_model)`
- Must support **cross-attention** (`seq_q != seq_k`)
- Do **NOT** use `torch.nn.MultiheadAttention`
- You **may** use `torch.softmax` and `torch.matmul`

### Steps
1. Project: `q = self.W_q(Q)`, `k = self.W_k(K)`, `v = self.W_v(V)`
2. Reshape to `(B, num_heads, seq, d_k)`
3. Scaled dot-product attention per head
4. Concat heads → `(B, seq_q, d_model)`
5. Output projection: `self.W_o(concat)`',
  'class MultiHeadAttention:',
  '',
  'Use nn.Linear for Q/K/V/O projections. d_k = d_model // num_heads. Reshape to (B, heads, S, d_k), SDPA per head, concat, output projection.',
  '# ✏️ YOUR IMPLEMENTATION HERE

class MultiHeadAttention:
    def __init__(self, d_model: int, num_heads: int):
        pass  # Initialize W_q, W_k, W_v, W_o

    def forward(self, Q, K, V):
        pass  # Implement multi-head attention',
  '[{"name": "Output shape", "code": "\nimport torch\ntorch.manual_seed(0)\nB, S, D, H = 2, 6, 32, 4\nmha = {fn}(d_model=D, num_heads=H)\nx = torch.randn(B, S, D)\nout = mha.forward(x, x, x)\nassert out.shape == (B, S, D), f''Shape mismatch: {out.shape} vs {(B, S, D)}''\n"}, {"name": "Uses nn.Linear with correct shapes", "code": "\nimport torch, torch.nn as nn\nmha = {fn}(d_model=32, num_heads=4)\nfor name in [''W_q'', ''W_k'', ''W_v'', ''W_o'']:\n    layer = getattr(mha, name)\n    assert isinstance(layer, nn.Linear), f''{name} should be nn.Linear, got {type(layer)}''\n    assert layer.weight.shape == (32, 32), f''{name}.weight shape: {layer.weight.shape}''\n    assert layer.weight.requires_grad, f''{name}.weight must require grad''\n"}, {"name": "Numerical correctness vs reference", "code": "\nimport torch, torch.nn as nn, math\ntorch.manual_seed(0)\nD, H = 16, 2\nd_k = D // H\nmha = {fn}(d_model=D, num_heads=H)\nQ = torch.randn(1, 4, D)\nK = torch.randn(1, 4, D)\nV = torch.randn(1, 4, D)\nout = mha.forward(Q, K, V)\nq = mha.W_q(Q).view(1, 4, H, d_k).transpose(1, 2)\nk = mha.W_k(K).view(1, 4, H, d_k).transpose(1, 2)\nv = mha.W_v(V).view(1, 4, H, d_k).transpose(1, 2)\nscores = torch.matmul(q, k.transpose(-2, -1)) / math.sqrt(d_k)\nweights = torch.softmax(scores, dim=-1)\nattn = torch.matmul(weights, v)\nref = mha.W_o(attn.transpose(1, 2).contiguous().view(1, 4, D))\nassert torch.allclose(out, ref, atol=1e-5), ''Output does not match reference''\n"}, {"name": "Gradient flow", "code": "\nimport torch\ntorch.manual_seed(0)\nmha = {fn}(d_model=16, num_heads=2)\nx = torch.randn(1, 4, 16, requires_grad=True)\nout = mha.forward(x, x, x)\nout.sum().backward()\nassert x.grad is not None, ''x.grad is None''\nassert mha.W_q.weight.grad is not None, ''W_q.weight.grad is None''\nassert mha.W_o.weight.grad is not None, ''W_o.weight.grad is None''\n"}, {"name": "Cross-attention (seq_q != seq_k)", "code": "\nimport torch\nmha = {fn}(d_model=32, num_heads=4)\nQ = torch.randn(1, 3, 32)\nK = torch.randn(1, 7, 32)\nV = torch.randn(1, 7, 32)\nout = mha.forward(Q, K, V)\nassert out.shape == (1, 3, 32), f''Cross-attention shape: {out.shape}''\n"}, {"name": "Different heads give different outputs", "code": "\nimport torch\ntorch.manual_seed(42)\nD, H = 16, 4\nd_k = D // H\nmha = {fn}(d_model=D, num_heads=H)\nx = torch.randn(1, 4, D)\nq = mha.W_q(x).view(1, 4, H, d_k).transpose(1, 2)\nassert not torch.allclose(q[:, 0], q[:, 1], atol=1e-3), ''Heads produce identical queries''\n"}]',
  '# ✅ SOLUTION

class MultiHeadAttention:
    def __init__(self, d_model: int, num_heads: int):
        self.num_heads = num_heads
        self.d_k = d_model // num_heads

        self.W_q = nn.Linear(d_model, d_model)
        self.W_k = nn.Linear(d_model, d_model)
        self.W_v = nn.Linear(d_model, d_model)
        self.W_o = nn.Linear(d_model, d_model)

    def forward(self, Q, K, V):
        B, S_q, _ = Q.shape
        S_k = K.shape[1]

        q = self.W_q(Q).view(B, S_q, self.num_heads, self.d_k).transpose(1, 2)
        k = self.W_k(K).view(B, S_k, self.num_heads, self.d_k).transpose(1, 2)
        v = self.W_v(V).view(B, S_k, self.num_heads, self.d_k).transpose(1, 2)

        scores = torch.matmul(q, k.transpose(-2, -1)) / math.sqrt(self.d_k)
        weights = torch.softmax(scores, dim=-1)
        attn = torch.matmul(weights, v)

        out = attn.transpose(1, 2).contiguous().view(B, S_q, -1)
        return self.W_o(out)',
  '# 🔴 Solution: Multi-Head Attention

Reference solution for the Multi-Head Attention mechanism.

$$\text{MultiHead}(Q, K, V) = \text{Concat}(\text{head}_1, \dots, \text{head}_h) W^O$$',
  'approved',
  11
)
