INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'sliding_window',
  'Sliding Window Attention',
  'Hard',
  '注意力机制',
  'sliding_window_attention',
  '# 🔴 Hard: Sliding Window Attention

Implement **Sliding Window Attention** — used in Longformer, Mistral, etc. for efficient long-context processing.

Each position $i$ can only attend to positions $j$ where $|i - j| \le w$ (the window size).

### Signature
```python
def sliding_window_attention(Q, K, V, window_size):
    # Q, K, V: (batch, seq, d) → output: (batch, seq, d_v)
    # window_size: int — position i attends to [i-w, i+w]
```

### Rules
- Do **NOT** use sparse attention libraries
- Mask positions outside the window with `-inf`
- `window_size=0`: only self — output should equal V
- `window_size >= seq_len`: equivalent to full attention',
  'def sliding_window_attention(Q, K, V, window_size):',
  '',
  'Like softmax attention but position i only attends to positions j where |i-j| <= window_size. Mask the rest with -inf.',
  '# ✏️ YOUR IMPLEMENTATION HERE

def sliding_window_attention(Q, K, V, window_size):
    pass  # Replace this',
  '[{"name": "Output shape", "code": "\nimport torch\nout = {fn}(torch.randn(2, 8, 16), torch.randn(2, 8, 16), torch.randn(2, 8, 16), window_size=2)\nassert out.shape == (2, 8, 16), f''Shape mismatch: {out.shape}''\n"}, {"name": "window_size=0 — only sees itself", "code": "\nimport torch\nQ = torch.randn(1, 4, 8)\nK = torch.randn(1, 4, 8)\nV = torch.randn(1, 4, 8)\nout = {fn}(Q, K, V, window_size=0)\nassert torch.allclose(out, V, atol=1e-5), ''window=0: each position should output V[i]''\n"}, {"name": "Large window equals full attention", "code": "\nimport torch, math\ntorch.manual_seed(0)\nB, S, D = 2, 6, 8\nQ = torch.randn(B, S, D)\nK = torch.randn(B, S, D)\nV = torch.randn(B, S, D)\nout_win = {fn}(Q, K, V, window_size=S)\nd_k = K.size(-1)\nscores = torch.bmm(Q, K.transpose(1, 2)) / math.sqrt(d_k)\nref = torch.bmm(torch.softmax(scores, dim=-1), V)\nassert torch.allclose(out_win, ref, atol=1e-5), ''Large window should equal full attention''\n"}, {"name": "Distant tokens don''t affect output", "code": "\nimport torch\ntorch.manual_seed(0)\nB, S, D = 1, 10, 8\nQ = torch.randn(B, S, D)\nK = torch.randn(B, S, D)\nV = torch.randn(B, S, D)\nout1 = {fn}(Q, K, V, window_size=1)\nK2, V2 = K.clone(), V.clone()\nK2[:, 5:] = torch.randn(B, 5, D)\nV2[:, 5:] = torch.randn(B, 5, D)\nout2 = {fn}(Q, K2, V2, window_size=1)\nassert torch.allclose(out1[:, 0], out2[:, 0], atol=1e-5), ''Distant tokens should not affect output''\n"}, {"name": "Gradient flow", "code": "\nimport torch\nQ = torch.randn(2, 4, 8, requires_grad=True)\nK = torch.randn(2, 4, 8, requires_grad=True)\nV = torch.randn(2, 4, 8, requires_grad=True)\n{fn}(Q, K, V, window_size=1).sum().backward()\nassert Q.grad is not None, ''Q.grad is None''\n"}]',
  '# ✅ SOLUTION

def sliding_window_attention(Q, K, V, window_size):
    d_k = K.size(-1)
    scores = torch.bmm(Q, K.transpose(1, 2)) / math.sqrt(d_k)
    S = Q.size(1)
    idx = torch.arange(S, device=Q.device)
    mask = (idx.unsqueeze(0) - idx.unsqueeze(1)).abs() > window_size
    scores = scores.masked_fill(mask.unsqueeze(0), float(''-inf''))
    weights = torch.softmax(scores, dim=-1)
    return torch.bmm(weights, V)',
  '# 🔴 Solution: Sliding Window Attention

Reference solution — softmax attention with a band mask.',
  'approved',
  12
)
