INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'gpt2_block',
  'GPT-2 Transformer Block',
  'Hard',
  '完整架构',
  'GPT2Block',
  '# 🔴 Hard: GPT-2 Transformer Block

Implement a full **GPT-2 style Transformer block** — combining everything you''ve learned.

### Architecture (Pre-Norm)
```
x = x + causal_self_attention(ln1(x))
x = x + mlp(ln2(x))
```

### Signature
```python
class GPT2Block(nn.Module):
    def __init__(self, d_model: int, num_heads: int): ...
    def forward(self, x: torch.Tensor) -> torch.Tensor: ...
```

### Requirements
- Inherit from `nn.Module`
- `self.ln1`, `self.ln2`: `nn.LayerNorm(d_model)`
- `self.W_q`, `self.W_k`, `self.W_v`, `self.W_o`: `nn.Linear` for attention
- `self.mlp`: `nn.Sequential(Linear(d, 4d), GELU(), Linear(4d, d))`
- Attention must be **causal** (mask future positions)
- Pre-norm architecture (LayerNorm *before* attention and MLP)
- Residual connections around both attention and MLP',
  'class GPT2Block(nn.Module):',
  '',
  'Pre-norm: x = x + attn(ln1(x)), x = x + mlp(ln2(x)). MLP: Linear(d, 4d) -> GELU -> Linear(4d, d). Attention must be causal. Inherit from nn.Module.',
  '# ✏️ YOUR IMPLEMENTATION HERE

class GPT2Block(nn.Module):
    def __init__(self, d_model, num_heads):
        super().__init__()
        pass  # Initialize layers

    def forward(self, x):
        pass  # Pre-norm + causal attention + MLP with residuals',
  '[{"name": "Output shape", "code": "\nimport torch, torch.nn as nn\ntorch.manual_seed(0)\nblock = {fn}(d_model=64, num_heads=4)\nassert isinstance(block, nn.Module), ''GPT2Block should inherit from nn.Module''\nout = block(torch.randn(2, 8, 64))\nassert out.shape == (2, 8, 64), f''Shape mismatch: {out.shape}''\n"}, {"name": "Has LayerNorm (pre-norm architecture)", "code": "\nimport torch, torch.nn as nn\nblock = {fn}(d_model=32, num_heads=4)\nassert hasattr(block, ''ln1'') and isinstance(block.ln1, nn.LayerNorm), ''Need self.ln1 = nn.LayerNorm''\nassert hasattr(block, ''ln2'') and isinstance(block.ln2, nn.LayerNorm), ''Need self.ln2 = nn.LayerNorm''\n"}, {"name": "MLP has 4x expansion with GELU", "code": "\nimport torch, torch.nn as nn\nblock = {fn}(d_model=32, num_heads=4)\nassert hasattr(block, ''mlp''), ''Need self.mlp''\nlinears = [m for m in block.mlp.modules() if isinstance(m, nn.Linear)]\nassert len(linears) >= 2, f''MLP needs >= 2 Linear layers, got {len(linears)}''\nassert linears[0].weight.shape == (128, 32), f''MLP first layer: {linears[0].weight.shape}, expected (128, 32)''\nassert linears[-1].weight.shape == (32, 128), f''MLP last layer: {linears[-1].weight.shape}, expected (32, 128)''\n"}, {"name": "Causal masking — future doesn''t affect past", "code": "\nimport torch\ntorch.manual_seed(0)\nblock = {fn}(d_model=32, num_heads=4)\nx = torch.randn(1, 8, 32)\nout1 = block(x)\nx2 = x.clone()\nx2[:, 4:] = torch.randn(1, 4, 32)\nout2 = block(x2)\nassert torch.allclose(out1[:, :4], out2[:, :4], atol=1e-5), ''Future tokens affected past — not causal''\n"}, {"name": "Gradient flow to all parameters", "code": "\nimport torch\ntorch.manual_seed(0)\nblock = {fn}(d_model=32, num_heads=4)\nx = torch.randn(1, 4, 32, requires_grad=True)\nblock(x).sum().backward()\nassert x.grad is not None, ''x.grad is None''\nn_total = sum(1 for p in block.parameters())\nn_grad = sum(1 for p in block.parameters() if p.grad is not None)\nassert n_grad == n_total, f''Only {n_grad}/{n_total} params got gradients''\n"}]',
  '# ✅ SOLUTION

class GPT2Block(nn.Module):
    def __init__(self, d_model, num_heads):
        super().__init__()
        self.num_heads = num_heads
        self.d_k = d_model // num_heads

        self.ln1 = nn.LayerNorm(d_model)
        self.ln2 = nn.LayerNorm(d_model)

        self.W_q = nn.Linear(d_model, d_model)
        self.W_k = nn.Linear(d_model, d_model)
        self.W_v = nn.Linear(d_model, d_model)
        self.W_o = nn.Linear(d_model, d_model)

        self.mlp = nn.Sequential(
            nn.Linear(d_model, 4 * d_model),
            nn.GELU(),
            nn.Linear(4 * d_model, d_model),
        )

    def _attn(self, x):
        B, S, _ = x.shape
        q = self.W_q(x).view(B, S, self.num_heads, self.d_k).transpose(1, 2)
        k = self.W_k(x).view(B, S, self.num_heads, self.d_k).transpose(1, 2)
        v = self.W_v(x).view(B, S, self.num_heads, self.d_k).transpose(1, 2)
        scores = torch.matmul(q, k.transpose(-2, -1)) / math.sqrt(self.d_k)
        mask = torch.triu(torch.ones(S, S, device=x.device, dtype=torch.bool), diagonal=1)
        scores = scores.masked_fill(mask, float(''-inf''))
        weights = torch.softmax(scores, dim=-1)
        attn = torch.matmul(weights, v)
        return self.W_o(attn.transpose(1, 2).contiguous().view(B, S, -1))

    def forward(self, x):
        x = x + self._attn(self.ln1(x))
        x = x + self.mlp(self.ln2(x))
        return x',
  '# 🔴 Solution: GPT-2 Transformer Block

Reference solution — pre-norm, causal self-attention, 4x MLP with GELU.',
  'approved',
  13
)
