INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'gelu',
  'GELU Activation',
  'Medium',
  '现代激活函数',
  'gelu',
  '# 🟡 Medium: GELU Activation

Implement the **GELU** (Gaussian Error Linear Unit) activation function from scratch.
Used in BERT, GPT, and modern Diffusion models.

$$\text{GELU}(x) = x \cdot \Phi(x)$$

where $\Phi(x)$ is the Gaussian CDF: $\Phi(x) = \frac{1}{2}\left(1 + \text{erf}\left(\frac{x}{\sqrt{2}}\right)\right)$

### Signature
```python
def gelu(x: torch.Tensor) -> torch.Tensor:
    ...
```

### Rules
- Do NOT use `torch.nn.functional.gelu` or built-in GELU
- You MAY use `torch.erf` for the exact formula
- Must support autograd

### Hint
Fast approximation: $0.5x\left(1 + \tanh\left(\sqrt{\frac{2}{\pi}}(x + 0.044715x^3)\right)\right)$',
  'def gelu(x: torch.Tensor) -> torch.Tensor:',
  '',
  'GELU(x) = x * Φ(x) where Φ is Gaussian CDF. Use erf: Φ(x) = 0.5 * (1 + erf(x / sqrt(2))). Fast approximation: 0.5 * x * (1 + tanh(sqrt(2/π) * (x + 0.044715 * x³))).',
  '# ✏️ YOUR IMPLEMENTATION HERE

def gelu(x: torch.Tensor) -> torch.Tensor:
    pass  # Replace this',
  '[{"name": "Basic values", "code": "\nimport torch, math\nx = torch.tensor([-2., -1., 0., 1., 2.])\nout = {fn}(x)\n# GELU(0) = 0, GELU(x) > 0 for x > 0, GELU(x) < 0 but small for x < 0\nassert abs(out[2].item()) < 1e-6, f''GELU(0) should be ~0, got {out[2]}''\nassert out[3] > 0.8, f''GELU(1) should be ~0.841, got {out[3]}''\nassert out[0] < 0, f''GELU(-2) should be negative, got {out[0]}''\nassert out[0] > -0.05, f''GELU(-2) should be small negative, got {out[0]}''\n"}, {"name": "Numerical accuracy vs reference", "code": "\nimport torch, math\nx = torch.linspace(-4, 4, 100)\nout = {fn}(x)\nref = 0.5 * x * (1 + torch.erf(x / math.sqrt(2)))\nassert torch.allclose(out, ref, atol=1e-5), f''Max diff: {(out - ref).abs().max()}''\n"}, {"name": "Gradient check", "code": "\nimport torch, math\nx = torch.tensor([-1., 0., 1., 2.], requires_grad=True)\nout = {fn}(x)\nout.sum().backward()\nassert x.grad is not None, ''No gradient''\n# GELU''(x) = Φ(x) + x * φ(x) where φ is Gaussian PDF\n# At x=1: ~0.841 + 1 * 0.242 = ~1.083\nassert x.grad[2] > 0.5, f''GELU\\''(1) should be > 0.5, got {x.grad[2]}''\nassert x.grad[2] < 1.5, f''GELU\\''(1) should be < 1.5, got {x.grad[2]}''\n"}, {"name": "2-D tensor", "code": "\nimport torch\nx = torch.randn(4, 8)\nout = {fn}(x)\nassert out.shape == x.shape, f''Shape mismatch''\nassert torch.allclose(out, torch.nn.functional.gelu(x), atol=1e-4), ''Should match nn.functional.gelu''\n"}, {"name": "Smooth transition at zero", "code": "\nimport torch\nx = torch.linspace(-0.1, 0.1, 20)\nout = {fn}(x)\n# GELU should be smooth (no sharp edges like ReLU)\ndiffs = out[1:] - out[:-1]\nassert (diffs >= 0).all(), ''GELU should be monotonically increasing''\n"}]',
  '# ✅ SOLUTION (Exact formula)

def gelu(x: torch.Tensor) -> torch.Tensor:
    return 0.5 * x * (1 + torch.erf(x / math.sqrt(2)))',
  '# 🟡 Solution: GELU Activation

Reference solution for GELU using the exact formula with erf.',
  'approved',
  15
)
