VALUES (
  'swiglu',
  'SwiGLU Activation',
  'Hard',
  '现代激活函数',
  'SwiGLU',
  '# 🔴 Hard: SwiGLU Activation

Implement **SwiGLU**, the activation used in LLaMA, PaLM and modern LLMs.

$$\text{SwiGLU}(x) = \text{SiLU}(xW_{gate}) \odot (xW_{up})$$

This combines gated linear units with Swish activation for better performance.

### Signature
```python
class SwiGLU(nn.Module):
    def __init__(self, d_in: int, d_out: int):
        ...
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        ...
```

### Requirements
- Use `nn.Linear` for `gate_proj` and `up_proj`
- Apply SiLU to the gate projection
- Element-wise multiply with up projection',
  'class SwiGLU(nn.Module):',
  '',
  'SwiGLU(x) = Swish(gate) * up where gate and up are projections. Swish(x) = x * sigmoid(x). Use nn.Linear for gate_proj and up_proj. d_out = d_in // 2 or configurable.',
  '# ✏️ YOUR IMPLEMENTATION HERE

class SwiGLU(nn.Module):
    def __init__(self, d_in: int, d_out: int):
        super().__init__()
        # ...
    
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ...
        pass',
  '[{"name": "Output shape", "code": "\nimport torch, torch.nn as nn\ntorch.manual_seed(0)\nglu = {fn}(d_in=32, d_out=32)\nx = torch.randn(2, 6, 32)\nout = glu(x)\nassert out.shape == (2, 6, 32), f''Shape mismatch: {out.shape}''\n"}, {"name": "Has correct linear projections", "code": "\nimport torch, torch.nn as nn\nglu = {fn}(d_in=64, d_out=64)\nassert hasattr(glu, ''gate_proj''), ''Need self.gate_proj = nn.Linear''\nassert hasattr(glu, ''up_proj''), ''Need self.up_proj = nn.Linear''\nassert isinstance(glu.gate_proj, nn.Linear), ''gate_proj should be nn.Linear''\nassert isinstance(glu.up_proj, nn.Linear), ''up_proj should be nn.Linear''\n"}, {"name": "SwiGLU vs GLU difference", "code": "\nimport torch, torch.nn as nn\ntorch.manual_seed(0)\nglu = {fn}(d_in=16, d_out=16)\nx = torch.randn(1, 4, 16)\nout = glu(x)\ngate = glu.gate_proj(x)\nup = glu.up_proj(x)\nswish = gate * torch.sigmoid(gate)\nref = swish * up\nassert torch.allclose(out, ref, atol=1e-5), ''SwiGLU = Swish(gate) * up''\n"}, {"name": "Gradient flow", "code": "\nimport torch\nglu = {fn}(d_in=16, d_out=16)\nx = torch.randn(1, 4, 16, requires_grad=True)\nout = glu(x)\nout.sum().backward()\nassert x.grad is not None, ''x.grad is None''\nassert glu.gate_proj.weight.grad is not None, ''gate_proj.weight.grad is None''\nassert glu.up_proj.weight.grad is not None, ''up_proj.weight.grad is None''\n"}, {"name": "Different from simple linear", "code": "\nimport torch, torch.nn as nn\ntorch.manual_seed(42)\nglu = {fn}(d_in=32, d_out=32)\nlinear = nn.Linear(32, 32)\nx = torch.randn(1, 4, 32)\nglu_out = glu(x)\n# SwiGLU should have different output than simple linear\nassert not torch.allclose(glu_out, linear(x), atol=0.1), ''SwiGLU should differ from simple linear''\n"}]',
  '# ✅ SOLUTION

class SwiGLU(nn.Module):
    def __init__(self, d_in: int, d_out: int):
        super().__init__()
        self.gate_proj = nn.Linear(d_in, d_out, bias=False)
        self.up_proj = nn.Linear(d_in, d_out, bias=False)
    
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        gate = self.gate_proj(x)
        up = self.up_proj(x)
        # SiLU = x * sigmoid(x)
        swish = gate * torch.sigmoid(gate)
        return swish * up',
  '# 🔴 Solution: SwiGLU Activation',
  'approved',
  16
)
