INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'dora',
  'DoRA Linear Layer',
  'Hard',
  '参数高效微调',
  'DoRALinear',
  '# 🔴 Hard: DoRA (Weight-Decomposed LoRA)

Implement **DoRA**, an improved variant of LoRA that decomposes weights into magnitude and direction.

DoRA decomposes $W$ into magnitude $m$ and direction $V$:
$$W = m \cdot \frac{V}{||V||}$$

LoRA updates the direction: $V'' = V + BA$

Final weight: $W'' = m \cdot \frac{V + BA}{||V + BA||}$

### Signature
```python
class DoRALinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, rank: int, alpha: float = 1.0):
        ...
```

### Requirements
- Initialize $m$ as the L2 norm of $W$ per output dimension
- Initialize $B$ with zeros
- Apply normalization to $V + BA$ before multiplying by $m$',
  'class DoRALinear(nn.Module):',
  '',
  'DoRA decomposes W into magnitude m and direction V: W = m * V/||V||. LoRA updates V: V'' = V + BA. Final: W'' = m * (V + BA) / ||V + BA||. This separates magnitude and direction learning.',
  '# ✏️ YOUR IMPLEMENTATION HERE

class DoRALinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, rank: int, alpha: float = 1.0):
        super().__init__()
        # ...
    
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ...
        pass',
  '[{"name": "Output shape", "code": "\nimport torch\ndora = {fn}(in_features=64, out_features=128, rank=8)\nx = torch.randn(2, 10, 64)\nout = dora(x)\nassert out.shape == (2, 10, 128), f''Shape mismatch: {out.shape}''\n"}, {"name": "Has required components", "code": "\nimport torch, torch.nn as nn\ndora = {fn}(in_features=32, out_features=64, rank=4)\nassert hasattr(dora, ''W''), ''Need self.W (base weight)''\nassert hasattr(dora, ''m''), ''Need self.m (magnitude vector)''\nassert hasattr(dora, ''A''), ''Need self.A (LoRA down)''\nassert hasattr(dora, ''B''), ''Need self.B (LoRA up)''\nassert dora.m.shape == (64,), f''m shape: {dora.m.shape}, expected (64,)''\n"}, {"name": "Magnitude initialized from base weight", "code": "\nimport torch\ndora = {fn}(in_features=32, out_features=64, rank=4)\n# m should be initialized as ||W||_2 per output dimension\nW_norm = dora.W.norm(dim=1)\nassert torch.allclose(dora.m, W_norm, atol=1e-5), ''m should be ||W||_2''\n"}, {"name": "B initialized to zero", "code": "\nimport torch\ndora = {fn}(in_features=32, out_features=64, rank=4)\nassert torch.allclose(dora.B, torch.zeros_like(dora.B)), ''B should be zero-initialized''\n"}, {"name": "DoRA applies weight decomposition", "code": "\nimport torch\ntorch.manual_seed(0)\ndora = {fn}(in_features=16, out_features=32, rank=2)\nx = torch.randn(1, 4, 16)\n# Manually compute DoRA output\nV = dora.W\nW_eff = dora.m.view(-1, 1) * V / V.norm(dim=1, keepdim=True)\nbase_out = x @ W_eff.T\nout = dora(x)\nassert torch.allclose(out, base_out, atol=1e-4), ''DoRA output should match decomposed W''\n"}, {"name": "Gradient flow", "code": "\nimport torch\ndora = {fn}(in_features=16, out_features=32, rank=4)\nx = torch.randn(1, 4, 16, requires_grad=True)\ndora(x).sum().backward()\nassert x.grad is not None, ''x.grad is None''\nassert dora.m.grad is not None, ''m.grad is None''\nassert dora.A.grad is not None, ''A.grad is None''\nassert dora.B.grad is not None, ''B.grad is None''\n"}, {"name": "DoRA differs from LoRA", "code": "\nimport torch\ntorch.manual_seed(42)\n# DoRA with non-zero B should differ from LoRA due to normalization\ndora = {fn}(in_features=16, out_features=32, rank=4)\nwith torch.no_grad():\n    dora.B.fill_(0.1)\nx = torch.randn(1, 4, 16)\n# Compute LoRA-style output\nlora_out = x @ dora.W.T + x @ dora.A.T @ dora.B.T * (dora.alpha / dora.rank)\ndora_out = dora(x)\nassert not torch.allclose(lora_out, dora_out, atol=1e-3), ''DoRA should differ from LoRA due to normalization''\n"}]',
  '# ✅ SOLUTION

class DoRALinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, rank: int, alpha: float = 1.0):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.rank = rank
        self.alpha = alpha
        
        # Base weight V (direction)
        self.W = nn.Parameter(torch.empty(out_features, in_features))
        nn.init.kaiming_uniform_(self.W)
        
        # Magnitude vector (initialized from W''s norm)
        self.m = nn.Parameter(self.W.norm(dim=1))
        
        # LoRA matrices
        self.A = nn.Parameter(torch.empty(rank, in_features))
        self.B = nn.Parameter(torch.zeros(out_features, rank))
        nn.init.kaiming_uniform_(self.A)
    
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Compute effective weight: m * (V + BA) / ||V + BA||
        V = self.W
        BA = self.B @ self.A * (self.alpha / self.rank) if self.rank > 0 else 0
        W_eff = V + BA
        W_eff = self.m.view(-1, 1) * W_eff / W_eff.norm(dim=1, keepdim=True)
        return x @ W_eff.T',
  '# 🔴 Solution: DoRA Linear Layer',
  'approved',
  17
)
