VALUES (
  'lora',
  'LoRA Linear Layer',
  'Hard',
  '参数高效微调',
  'LoRALinear',
  '# 🔴 Hard: LoRA (Low-Rank Adaptation)

Implement **LoRA** for parameter-efficient fine-tuning of large models.

LoRA adds a low-rank decomposition to existing weights:
$$W'' = W + \Delta W = W + \frac{\alpha}{r}BA$$

Where $B \in \mathbb{R}^{d_{out} \times r}$ and $A \in \mathbb{R}^{r \times d_{in}}$.

### Signature
```python
class LoRALinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, rank: int, alpha: float = 1.0):
        ...
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        ...
```

### Requirements
- Initialize B with zeros (so LoRA starts as identity)
- Initialize A with Kaiming uniform or normal
- Forward: `x @ W.T + (x @ A.T @ B.T) * alpha / rank`',
  'class LoRALinear(nn.Module):',
  '',
  'LoRA: W'' = W + BA where B (d_out × r) and A (r × d_in). Alpha scales: ΔW = (α/r) * BA. Initialize A with Kaiming/normal, B with zeros. Forward: x @ W.T + (x @ A.T @ B.T) * α/r.',
  '# ✏️ YOUR IMPLEMENTATION HERE

class LoRALinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, rank: int, alpha: float = 1.0):
        super().__init__()
        # ...
    
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ...
        pass',
  '[{"name": "Output shape", "code": "\nimport torch, torch.nn as nn\nlora = {fn}(in_features=64, out_features=128, rank=8)\nx = torch.randn(2, 10, 64)\nout = lora(x)\nassert out.shape == (2, 10, 128), f''Shape mismatch: {out.shape}''\n"}, {"name": "Has required components", "code": "\nimport torch, torch.nn as nn\nlora = {fn}(in_features=32, out_features=64, rank=4)\nassert hasattr(lora, ''W''), ''Need self.W (base weight)''\nassert hasattr(lora, ''A''), ''Need self.A (down projection)''\nassert hasattr(lora, ''B''), ''Need self.B (up projection)''\nassert lora.A.shape == (4, 32), f''A shape: {lora.A.shape}, expected (4, 32)''\nassert lora.B.shape == (64, 4), f''B shape: {lora.B.shape}, expected (64, 4)''\n"}, {"name": "B initialized to zero", "code": "\nimport torch\nlora = {fn}(in_features=32, out_features=64, rank=4)\n# B should be zero-initialized so LoRA starts as identity (W'' = W)\nassert torch.allclose(lora.B, torch.zeros_like(lora.B)), ''B should be zero-initialized''\n"}, {"name": "LoRA adds to base output", "code": "\nimport torch, torch.nn as nn\ntorch.manual_seed(0)\nlora = {fn}(in_features=16, out_features=32, rank=2, alpha=4.0)\nx = torch.randn(1, 4, 16)\n# Set A and B to known values\nwith torch.no_grad():\n    lora.A.fill_(0.1)\n    lora.B.fill_(0.2)\nout = lora(x)\nbase = x @ lora.W.T\nlora_delta = x @ lora.A.T @ lora.B.T * (lora.alpha / lora.rank)\nref = base + lora_delta\nassert torch.allclose(out, ref, atol=1e-5), ''LoRA should add scaled BA to base output''\n"}, {"name": "Gradient flow", "code": "\nimport torch\nlora = {fn}(in_features=16, out_features=32, rank=4)\nx = torch.randn(1, 4, 16, requires_grad=True)\nout = lora(x)\nout.sum().backward()\nassert x.grad is not None, ''x.grad is None''\nassert lora.A.grad is not None, ''A.grad is None''\nassert lora.B.grad is not None, ''B.grad is None''\n"}, {"name": "Rank controls parameter efficiency", "code": "\nimport torch, torch.nn as nn\nlora = {fn}(in_features=64, out_features=128, rank=8)\nlora_params = sum(p.numel() for p in lora.parameters())\n# Base weight: W (128×64) = 8192 params\n# LoRA adds: A (8×64) + B (128×8) = 512 + 1024 = 1536 extra params\nbase_w = 64 * 128\nextra = 8 * 64 + 128 * 8\nassert lora_params >= base_w + extra, f''Expected at least {base_w + extra} params (base W + LoRA A,B), got {lora_params}''\n"}, {"name": "Zero rank means identity LoRA", "code": "\nimport torch\nlora = {fn}(in_features=32, out_features=64, rank=0)\nx = torch.randn(1, 4, 32)\nout = lora(x)\nbase = x @ lora.W.T\nassert torch.allclose(out, base, atol=1e-6), ''rank=0 should be pure base layer''\n"}]',
  '# ✅ SOLUTION

class LoRALinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, rank: int, alpha: float = 1.0):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.rank = rank
        self.alpha = alpha
        
        # Base weight
        self.W = nn.Parameter(torch.empty(out_features, in_features))
        nn.init.kaiming_uniform_(self.W)
        
        if rank > 0:
            # LoRA matrices
            self.A = nn.Parameter(torch.empty(rank, in_features))
            self.B = nn.Parameter(torch.zeros(out_features, rank))
            nn.init.kaiming_uniform_(self.A)
        else:
            self.A = nn.Parameter(torch.empty(0, in_features), requires_grad=False)
            self.B = nn.Parameter(torch.empty(out_features, 0), requires_grad=False)
    
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Base output
        out = x @ self.W.T
        
        # LoRA addition
        if self.rank > 0:
            out = out + (x @ self.A.T @ self.B.T) * (self.alpha / self.rank)
        
        return out',
  '# 🔴 Solution: LoRA Linear Layer',
  'approved',
  18
)
