  'FiLM',
  '# 🟡 Medium: FiLM (Feature-wise Linear Modulation)

Implement **FiLM**, a simple but powerful conditional modulation technique.

$$\text{FiLM}(x, c) = \gamma(c) \odot x + \beta(c)$$

Where $\gamma$ and $\beta$ are predicted from condition $c$.

### Signature
```python
class FiLM(nn.Module):
    def __init__(self, feature_dim: int, cond_dim: int):
        ...
    def forward(self, x: torch.Tensor, cond: torch.Tensor) -> torch.Tensor:
        ...
```

### Requirements
- Use Linear layers to predict $\gamma$ and $\beta$ from condition
- Apply affine transform to input features',
  'class FiLM(nn.Module):',
  '',
  'FiLM applies affine transform conditioned on input: γ(c) * x + β(c). Use a small MLP to predict scale γ and shift β from condition. Simple but powerful for style transfer and conditional generation.',
  '# ✏️ YOUR IMPLEMENTATION HERE

class FiLM(nn.Module):
    def __init__(self, feature_dim: int, cond_dim: int):
        super().__init__()
        # ...
    
    def forward(self, x: torch.Tensor, cond: torch.Tensor) -> torch.Tensor:
        # ...
        pass',
  '[{"name": "Output shape", "code": "\nimport torch\nfilm = {fn}(feature_dim=64, cond_dim=32)\nx = torch.randn(2, 10, 64)\ncond = torch.randn(2, 32)\nout = film(x, cond)\nassert out.shape == (2, 10, 64), f''Shape mismatch: {out.shape}''\n"}, {"name": "Has modulation parameters", "code": "\nimport torch, torch.nn as nn\nfilm = {fn}(feature_dim=32, cond_dim=16)\nassert hasattr(film, ''gamma_fc'') or hasattr(film, ''beta_fc''), ''Need gamma_fc and beta_fc for modulation''\n"}, {"name": "Applies affine modulation", "code": "\nimport torch\nfilm = {fn}(feature_dim=32, cond_dim=16)\nx = torch.randn(1, 4, 32)\ncond = torch.randn(1, 16)\nout = film(x, cond)\n# FiLM should apply gamma * x + beta\n# Without proper implementation, this test verifies the structure\nassert out.shape == x.shape, ''Output shape should match input''\n"}, {"name": "Condition affects output", "code": "\nimport torch\nfilm = {fn}(feature_dim=32, cond_dim=16)\nx = torch.randn(1, 4, 32)\ncond1 = torch.zeros(1, 16)\ncond2 = torch.ones(1, 16)\nout1 = film(x, cond1)\nout2 = film(x, cond2)\nassert not torch.allclose(out1, out2, atol=1e-3), ''Different conditions should give different outputs''\n"}, {"name": "Gradient flow", "code": "\nimport torch\nfilm = {fn}(feature_dim=32, cond_dim=16)\nx = torch.randn(1, 4, 32, requires_grad=True)\ncond = torch.randn(1, 16, requires_grad=True)\nout = film(x, cond)\nout.sum().backward()\nassert x.grad is not None, ''x.grad is None''\nassert cond.grad is not None, ''cond.grad is None''\n"}, {"name": "Identity when gamma=1, beta=0", "code": "\nimport torch\nfilm = {fn}(feature_dim=32, cond_dim=16)\nx = torch.randn(1, 4, 32)\n# If gamma=1 and beta=0, output should equal normalized input\n# This tests that the modulation structure is correct\nassert hasattr(film, ''gamma_fc'') or hasattr(film, ''fc_gamma'') or hasattr(film, ''mlp''), ''FiLM needs modulation layers''\n"}]',
  '# ✅ SOLUTION

class FiLM(nn.Module):
    def __init__(self, feature_dim: int, cond_dim: int):
        super().__init__()
        self.gamma_fc = nn.Linear(cond_dim, feature_dim)
        self.beta_fc = nn.Linear(cond_dim, feature_dim)
    
    def forward(self, x: torch.Tensor, cond: torch.Tensor) -> torch.Tensor:
        gamma = self.gamma_fc(cond).unsqueeze(1)  # (batch, 1, feature_dim)
        beta = self.beta_fc(cond).unsqueeze(1)  # (batch, 1, feature_dim)
        return gamma * x + beta',
  '# 🟡 Solution: FiLM Layer',
  'approved',
  19
)
