VALUES (
  'adaln',
  'AdaLN (Adaptive Layer Normalization)',
  'Hard',
  '条件调制 — Diffusion',
  'AdaLN',
  '# 🔴 Hard: AdaLN (Adaptive Layer Normalization)

Implement **AdaLN**, used in DiT and Diffusion Transformers for conditional generation.

AdaLN modulates LayerNorm using a conditioning signal:
$$\text{AdaLN}(x, c) = \gamma(c) \odot \text{LN}(x) + \beta(c)$$

Where $\gamma$ and $\beta$ are predicted from the condition $c$.

### Signature
```python
class AdaLN(nn.Module):
    def __init__(self, hidden_dim: int, cond_dim: int):
        ...
    def forward(self, x: torch.Tensor, cond: torch.Tensor) -> torch.Tensor:
        ...
```

### Requirements
- Use `nn.LayerNorm` for the base normalization
- Use a small MLP (SiLU + Linear) to predict $\gamma$ and $\beta$ from condition
- Shape: x is (batch, seq, hidden_dim), cond is (batch, cond_dim)',
  'class AdaLN(nn.Module):',
  '',
  'AdaLN modulates LayerNorm using conditioning: γ, β = f(cond). Use nn.SiLU + nn.Linear to predict scale and shift from condition. Output: γ * normalize(x) + β. γ typically initialized to 1, β to 0.',
  '# ✏️ YOUR IMPLEMENTATION HERE

class AdaLN(nn.Module):
    def __init__(self, hidden_dim: int, cond_dim: int):
        super().__init__()
        # ...
    
    def forward(self, x: torch.Tensor, cond: torch.Tensor) -> torch.Tensor:
        # ...
        pass',
  '[{"name": "Output shape", "code": "\nimport torch, torch.nn as nn\nadaln = {fn}(hidden_dim=64, cond_dim=128)\nx = torch.randn(2, 10, 64)\ncond = torch.randn(2, 128)\nout = adaln(x, cond)\nassert out.shape == (2, 10, 64), f''Shape mismatch: {out.shape}''\n"}, {"name": "Has modulation layers", "code": "\nimport torch, torch.nn as nn\nadaln = {fn}(hidden_dim=32, cond_dim=64)\nassert hasattr(adaln, ''norm''), ''Need self.norm = nn.LayerNorm''\nassert hasattr(adaln, ''cond_mlp''), ''Need self.cond_mlp for scale/shift prediction''\nassert isinstance(adaln.norm, nn.LayerNorm), ''norm should be nn.LayerNorm''\n"}, {"name": "Produces per-sample modulation", "code": "\nimport torch\nadaln = {fn}(hidden_dim=32, cond_dim=64)\nx = torch.randn(2, 10, 32)\ncond1 = torch.randn(2, 64)\ncond2 = torch.randn(2, 64)\nout1 = adaln(x, cond1)\nout2 = adaln(x, cond2)\n# Same x, different cond should give different outputs\nassert not torch.allclose(out1, out2, atol=1e-3), ''Different conditions should give different outputs''\n"}, {"name": "Condition-independent when gamma=1, beta=0", "code": "\nimport torch\nadaln = {fn}(hidden_dim=32, cond_dim=64)\nx = torch.randn(1, 4, 32)\n# Initialize to identity modulation\nwith torch.no_grad():\n    for p in adaln.cond_mlp.parameters():\n        p.zero_()\nout = adaln(x, torch.randn(1, 64))\n# With zero MLP, should approximate standard LayerNorm (gamma≈0 -> 1 after init)\nassert out.shape == x.shape, ''Output shape should match input''\n"}, {"name": "Gradient flow", "code": "\nimport torch\nadaln = {fn}(hidden_dim=32, cond_dim=64)\nx = torch.randn(1, 4, 32, requires_grad=True)\ncond = torch.randn(1, 64, requires_grad=True)\nout = adaln(x, cond)\nout.sum().backward()\nassert x.grad is not None, ''x.grad is None''\nassert cond.grad is not None, ''cond.grad is None''\n"}, {"name": "Modulation affects normalized output", "code": "\nimport torch\nadaln = {fn}(hidden_dim=32, cond_dim=64)\nx = torch.randn(1, 4, 32)\ncond = torch.randn(1, 64)\nout = adaln(x, cond)\n# Output should be normalized (zero mean, unit variance per token) before modulation\n# After modulation, it may have different statistics\nassert out.shape == x.shape\n# Check that modulation actually happened (not just LayerNorm)\nref_norm = torch.nn.functional.layer_norm(x, [32])\nassert not torch.allclose(out, ref_norm, atol=1e-3), ''AdaLN should differ from plain LayerNorm''\n"}]',
  '# ✅ SOLUTION

class AdaLN(nn.Module):
    def __init__(self, hidden_dim: int, cond_dim: int):
        super().__init__()
        self.norm = nn.LayerNorm(hidden_dim, elementwise_affine=False)
        self.cond_mlp = nn.Sequential(
            nn.SiLU(),
            nn.Linear(cond_dim, 2 * hidden_dim)  # gamma and beta
        )
    
    def forward(self, x: torch.Tensor, cond: torch.Tensor) -> torch.Tensor:
        # x: (batch, seq, hidden_dim)
        # cond: (batch, cond_dim)
        x_norm = self.norm(x)
        gamma_beta = self.cond_mlp(cond)  # (batch, 2 * hidden_dim)
        gamma, beta = gamma_beta.chunk(2, dim=-1)  # each (batch, hidden_dim)
        
        # Add sequence dimension and apply
        gamma = gamma.unsqueeze(1)  # (batch, 1, hidden_dim)
        beta = beta.unsqueeze(1)  # (batch, 1, hidden_dim)
        
        return gamma * x_norm + beta',
  '# 🔴 Solution: AdaLN',
  'approved',
  20
)
