VALUES (
  'adaln_zero',
  'AdaLN-Zero',
  'Hard',
  '条件调制 — Diffusion',
  'AdaLNZero',
  '# 🔴 Hard: AdaLN-Zero

Implement **AdaLN-Zero**, a variant with zero initialization for stable training.

Like AdaLN but with zero initialization so the model starts as identity:
- $\gamma = \beta = 0$ at initialization
- Includes a gate parameter for residual connections

### Signature
```python
class AdaLNZero(nn.Module):
    def __init__(self, hidden_dim: int, cond_dim: int):
        ...
```

### Requirements
- Final output projection must be zero-initialized
- Include a `gate_proj` for residual gate
- Output at init should be close to zero',
  'class AdaLNZero(nn.Module):',
  '',
  'AdaLN-Zero initializes the last linear layer to zero so γ=β=0 initially. Also includes a gate for residual. Output: gate * (γ * ln(x) + β). Gate initialized to 0, allowing the model to gradually increase modulation strength.',
  '# ✏️ YOUR IMPLEMENTATION HERE

class AdaLNZero(nn.Module):
    def __init__(self, hidden_dim: int, cond_dim: int):
        super().__init__()
        # ...
    
    def forward(self, x: torch.Tensor, cond: torch.Tensor) -> torch.Tensor:
        # ...
        pass',
  '[{"name": "Output shape", "code": "\nimport torch\nadaln = {fn}(hidden_dim=64, cond_dim=128)\nx = torch.randn(2, 10, 64)\ncond = torch.randn(2, 128)\nout = adaln(x, cond)\nassert out.shape == (2, 10, 64), f''Shape mismatch: {out.shape}''\n"}, {"name": "Zero initialization", "code": "\nimport torch\nadaln = {fn}(hidden_dim=32, cond_dim=64)\n# The final projection should be zero-initialized\n# This ensures γ=0, β=0, gate=0 at initialization\nx = torch.randn(1, 4, 32)\ncond = torch.randn(1, 64)\nout = adaln(x, cond)\n# With zero init, output should be close to zero\nassert torch.allclose(out, torch.zeros_like(out), atol=1e-5), f''Zero init should give zero output, got max {out.abs().max()}''\n"}, {"name": "Has gate parameter", "code": "\nimport torch, torch.nn as nn\nadaln = {fn}(hidden_dim=32, cond_dim=64)\nassert hasattr(adaln, ''gate_proj''), ''Need self.gate_proj for residual gate''\n"}, {"name": "Gate allows gradual learning", "code": "\nimport torch\nadaln = {fn}(hidden_dim=32, cond_dim=64)\nx = torch.randn(1, 4, 32)\ncond = torch.randn(1, 64)\n# Set non-zero modulation but zero gate\nwith torch.no_grad():\n    # Manually set gamma, beta but keep gate at zero\n    adaln.gate_proj.weight.zero_()\n    adaln.gate_proj.bias.zero_()\nout = adaln(x, cond)\nassert torch.allclose(out, torch.zeros_like(out), atol=1e-5), ''Zero gate should give zero output''\n"}, {"name": "Gradient flow", "code": "\nimport torch\nadaln = {fn}(hidden_dim=32, cond_dim=64)\nx = torch.randn(1, 4, 32, requires_grad=True)\ncond = torch.randn(1, 64, requires_grad=True)\nout = adaln(x, cond)\nout.sum().backward()\nassert x.grad is not None, ''x.grad is None''\nassert cond.grad is not None, ''cond.grad is None''\n"}, {"name": "Non-zero after training simulation", "code": "\nimport torch, torch.optim as optim\nadaln = {fn}(hidden_dim=32, cond_dim=64)\noptimizer = optim.SGD(adaln.parameters(), lr=0.1)\nx = torch.randn(1, 4, 32)\ncond = torch.randn(1, 64)\ntarget = torch.randn(1, 4, 32)\n# Simulate a few training steps\nfor _ in range(5):\n    out = adaln(x, cond)\n    loss = (out - target).pow(2).sum()\n    optimizer.zero_grad()\n    loss.backward()\n    optimizer.step()\nout_after = adaln(x, cond)\nassert not torch.allclose(out_after, torch.zeros_like(out_after), atol=1e-3), ''After training, output should be non-zero''\n"}]',
  '# ✅ SOLUTION

class AdaLNZero(nn.Module):
    def __init__(self, hidden_dim: int, cond_dim: int):
        super().__init__()
        self.norm = nn.LayerNorm(hidden_dim, elementwise_affine=False)
        
        # MLP for gamma, beta, and gate
        self.cond_mlp = nn.Sequential(
            nn.SiLU(),
            nn.Linear(cond_dim, 3 * hidden_dim)  # gamma, beta, gate
        )
        
        # Zero-initialize the final projection
        nn.init.zeros_(self.cond_mlp[1].weight)
        nn.init.zeros_(self.cond_mlp[1].bias)
        
        self.gate_proj = nn.Linear(cond_dim, hidden_dim)
        nn.init.zeros_(self.gate_proj.weight)
        nn.init.zeros_(self.gate_proj.bias)
    
    def forward(self, x: torch.Tensor, cond: torch.Tensor) -> torch.Tensor:
        x_norm = self.norm(x)
        gamma_beta_gate = self.cond_mlp(cond)
        gamma, beta, gate = gamma_beta_gate.chunk(3, dim=-1)
        
        gamma = gamma.unsqueeze(1)
        beta = beta.unsqueeze(1)
        gate = gate.unsqueeze(1)
        
        return gate * (gamma * x_norm + beta)',
  '# 🔴 Solution: AdaLN-Zero',
  'approved',
  21
)
