INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'rope',
  'Rotary Position Embedding (RoPE)',
  'Hard',
  'LLM 推理组件',
  'apply_rotary_pos_emb',
  '# 🔴 Hard: RoPE (Rotary Position Embedding)

Implement **RoPE**, the positional encoding used in LLaMA, Mistral, and GPT-NeoX.

RoPE applies rotation to pairs of dimensions based on position:

For position $m$ and dimension pair $(2i, 2i+1)$:
$$\theta_i = \frac{1}{10000^{2i/d}}$$
$$x_{2i}'' = x_{2i} \cos(m\theta_i) - x_{2i+1} \sin(m\theta_i)$$
$$x_{2i+1}'' = x_{2i} \sin(m\theta_i) + x_{2i+1} \cos(m\theta_i)$$

### Signature
```python
def apply_rotary_pos_emb(x: torch.Tensor, pos: torch.Tensor) -> torch.Tensor:
    # x: (batch, num_heads, seq_len, head_dim)
    # pos: (batch, seq_len) or (seq_len,)
    ...
```',
  'def apply_rotary_pos_emb(x: torch.Tensor, pos: torch.Tensor) -> torch.Tensor:',
  '',
  'RoPE applies rotation to pairs of dimensions. For position m and dimension pair (i, i+1): x_rotated = [x_i*cos(θ) - x_{i+1}*sin(θ), x_i*sin(θ) + x_{i+1}*cos(θ)]. θ = m * θ_i where θ_i = 1/(10000^(2i/d)).',
  '# ✏️ YOUR IMPLEMENTATION HERE

def apply_rotary_pos_emb(x: torch.Tensor, pos: torch.Tensor) -> torch.Tensor:
    # x: (batch, num_heads, seq_len, head_dim)
    # pos: (batch, seq_len) position indices
    pass  # Replace this',
  '[{"name": "Output shape", "code": "\nimport torch\nx = torch.randn(2, 4, 8, 16)  # (batch, heads, seq, head_dim)\npos = torch.arange(8).unsqueeze(0).expand(2, -1)  # (batch, seq)\nout = {fn}(x, pos)\nassert out.shape == x.shape, f''Shape mismatch: {out.shape}''\n"}, {"name": "Preserves norm", "code": "\nimport torch\nx = torch.randn(1, 2, 4, 16)\npos = torch.arange(4).unsqueeze(0)\nout = {fn}(x, pos)\nx_norm = x.norm(dim=-1)\nout_norm = out.norm(dim=-1)\nassert torch.allclose(x_norm, out_norm, atol=1e-5), ''RoPE should preserve vector norm''\n"}, {"name": "Position zero gives identity", "code": "\nimport torch\nx = torch.randn(1, 2, 4, 16)\npos = torch.zeros(1, 4, dtype=torch.long)\nout = {fn}(x, pos)\nassert torch.allclose(out, x, atol=1e-6), ''Position 0 should give identity (cos(0)=1, sin(0)=0)''\n"}, {"name": "Different positions give different outputs", "code": "\nimport torch\nx = torch.randn(1, 2, 1, 16)\npos1 = torch.zeros(1, 1, dtype=torch.long)\npos2 = torch.ones(1, 1, dtype=torch.long)\nout1 = {fn}(x, pos1)\nout2 = {fn}(x, pos2)\nassert not torch.allclose(out1, out2, atol=1e-3), ''Different positions should give different outputs''\n"}, {"name": "Gradient flow", "code": "\nimport torch\nx = torch.randn(1, 2, 4, 16, requires_grad=True)\npos = torch.arange(4).unsqueeze(0)\nout = {fn}(x, pos)\nout.sum().backward()\nassert x.grad is not None, ''x.grad is None''\n"}, {"name": "Handles even dimensions correctly", "code": "\nimport torch, math\nx = torch.randn(1, 1, 1, 8)  # head_dim = 8\npos = torch.tensor([[1]])\nout = {fn}(x, pos)\n# Verify rotation is applied to pairs\n# For pos=1, dim pair (0,1) should be rotated by θ_0 = 1/10000^0 = 1\n# Manual check: cos(1) ≈ 0.5403, sin(1) ≈ 0.8415\ntheta_0 = 1.0\nexpected_0 = x[0,0,0,0] * math.cos(theta_0) - x[0,0,0,1] * math.sin(theta_0)\nexpected_1 = x[0,0,0,0] * math.sin(theta_0) + x[0,0,0,1] * math.cos(theta_0)\nassert torch.allclose(out[0,0,0,0], expected_0, atol=1e-4), f''Dim 0 mismatch''\nassert torch.allclose(out[0,0,0,1], expected_1, atol=1e-4), f''Dim 1 mismatch''\n"}]',
  '# ✅ SOLUTION

def apply_rotary_pos_emb(x: torch.Tensor, pos: torch.Tensor) -> torch.Tensor:
    # x: (batch, num_heads, seq_len, head_dim)
    # pos: (batch, seq_len) position indices
    
    batch, num_heads, seq_len, head_dim = x.shape
    
    # Compute frequencies: theta_i = 1 / (10000^(2i/d))
    freqs = 1.0 / (10000 ** (torch.arange(0, head_dim, 2, device=x.device).float() / head_dim))
    
    # pos: (batch, seq_len) -> (batch, seq_len, 1)
    pos = pos.unsqueeze(-1).float()
    
    # angles: (batch, seq_len, head_dim/2)
    angles = pos * freqs.unsqueeze(0).unsqueeze(0)
    
    # cos and sin
    cos = torch.cos(angles)  # (batch, seq_len, head_dim/2)
    sin = torch.sin(angles)
    
    # Reshape x for rotation: split into pairs
    x1 = x[..., 0::2]  # (batch, num_heads, seq_len, head_dim/2)
    x2 = x[..., 1::2]
    
    # Apply rotation
    cos = cos.unsqueeze(1)  # (batch, 1, seq_len, head_dim/2)
    sin = sin.unsqueeze(1)
    
    x_rotated_1 = x1 * cos - x2 * sin
    x_rotated_2 = x1 * sin + x2 * cos
    
    # Interleave back
    x_out = torch.stack([x_rotated_1, x_rotated_2], dim=-1).flatten(-2)
    
    return x_out',
  '# 🔴 Solution: RoPE',
  'approved',
  23
)
