INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'snr',
  'Sigmoid Noise Schedule',
  'Medium',
  '扩散模型训练',
  'sigmoid_schedule',
  '# 🟡 Medium: Sigmoid Noise Schedule

Implement a **sigmoid noise schedule** for diffusion models.

A smooth schedule that creates an S-curve transition:
$$\beta(t) = \beta_{start} + (\beta_{end} - \beta_{start}) \cdot \sigma(\gamma(t - 0.5))$$

Where $\sigma$ is the sigmoid function and $\gamma$ controls steepness.

### Signature
```python
def sigmoid_schedule(t: torch.Tensor, beta_start: float, beta_end: float, gamma: float = 10.0) -> torch.Tensor:
    # t: normalized timesteps in [0, 1]
    # returns: beta values at each timestep
    ...
```',
  'def sigmoid_schedule(t: torch.Tensor, beta_start: float, beta_end: float, gamma: float = 10.0) -> torch.Tensor:',
  '',
  'Sigmoid schedule creates smooth transition between signal and noise. σ(t) = exp(σ_min + (σ_max - σ_min) * sigmoid(γ * (t - 0.5))). Or for β schedule: β(t) = sigmoid(...) mapped to [β_start, β_end].',
  '# ✏️ YOUR IMPLEMENTATION HERE

def sigmoid_schedule(t: torch.Tensor, beta_start: float, beta_end: float, gamma: float = 10.0) -> torch.Tensor:
    # t: normalized timesteps in [0, 1]
    pass  # Replace this',
  '[{"name": "Output shape", "code": "\nimport torch\nt = torch.linspace(0, 1, 100)\nbetas = {fn}(t, beta_start=0.0001, beta_end=0.02)\nassert betas.shape == t.shape, f''Shape mismatch: {betas.shape}''\n"}, {"name": "Bounds at endpoints", "code": "\nimport torch\nt = torch.tensor([0.0, 1.0])\nbetas = {fn}(t, beta_start=0.0001, beta_end=0.02)\nassert betas[0] < 0.001, f''beta at t=0 should be near beta_start, got {betas[0]}''\nassert betas[1] > 0.015, f''beta at t=1 should be near beta_end, got {betas[1]}''\n"}, {"name": "Monotonic increase", "code": "\nimport torch\nt = torch.linspace(0, 1, 100)\nbetas = {fn}(t, beta_start=0.0001, beta_end=0.02)\ndiffs = betas[1:] - betas[:-1]\nassert (diffs >= -1e-6).all(), ''Betas should be monotonically non-decreasing''\n"}, {"name": "Smooth transition", "code": "\nimport torch\nt = torch.linspace(0, 1, 100)\nbetas = {fn}(t, beta_start=0.0001, beta_end=0.02)\n# Sigmoid should give smooth S-curve, not linear\nmid = betas[49]  # t=0.5\nlinear_mid = 0.5 * (0.0001 + 0.02)\n# Sigmoid mid should be close to linear mid for standard sigmoid\nassert abs(mid - linear_mid) < 0.005, f''Mid point should be smooth transition''\n"}, {"name": "Different parameters give different schedules", "code": "\nimport torch\nt = torch.linspace(0, 1, 50)\nbetas1 = {fn}(t, beta_start=0.0001, beta_end=0.02)\nbetas2 = {fn}(t, beta_start=0.0001, beta_end=0.05)\nassert not torch.allclose(betas1, betas2, atol=1e-3), ''Different beta_end should give different schedule''\n"}]',
  '# ✅ SOLUTION

def sigmoid_schedule(t: torch.Tensor, beta_start: float, beta_end: float, gamma: float = 10.0) -> torch.Tensor:
    # t: normalized timesteps in [0, 1]
    # Sigmoid schedule creates smooth S-curve transition
    
    # Center the sigmoid around 0.5
    sig = torch.sigmoid(gamma * (t - 0.5))
    
    # Scale to [beta_start, beta_end]
    betas = beta_start + (beta_end - beta_start) * sig
    
    return betas',
  '# 🟡 Solution: Sigmoid Noise Schedule',
  'approved',
  24
)
