VALUES (
  'kmeans',
  'K-Means Clustering',
  'Medium',
  'ML 基础与解码策略',
  'kmeans',
  '# 🟡 Medium: K-Means Clustering

Implement **K-Means clustering** from scratch using PyTorch tensors.

Use a deterministic initialization rule: take the **first `num_clusters` points** as the initial centroids.

Then repeat:
1. Assign each point to its nearest centroid.
2. Recompute each centroid as the mean of its assigned points.
3. If a cluster becomes empty, keep its previous centroid.

### Signature
```python
def kmeans(x: torch.Tensor, num_clusters: int, num_iters: int = 10) -> tuple[torch.Tensor, torch.Tensor]:
    # x: (num_points, dim)
    # returns: (centroids, assignments)
    ...
```

### Rules
- Use only PyTorch tensor ops
- Do not call external clustering libraries
- `assignments` should contain the index of the nearest centroid for each point

### Example
```
x = tensor([[0., 0.],
            [5., 5.],
            [0., 1.],
            [6., 5.]])

centroids, assignments = kmeans(x, num_clusters=2, num_iters=5)
```',
  'def kmeans(x: torch.Tensor, num_clusters: int, num_iters: int = 10) -> tuple[torch.Tensor, torch.Tensor]:',
  'x = tensor([[0., 0.],
            [5., 5.],
            [0., 1.],
            [6., 5.]])

centroids, assignments = kmeans(x, num_clusters=2, num_iters=5)',
  'Initialize centroids from the first k points for deterministic behavior. Then alternate: assign each point to the nearest centroid, and recompute each centroid as the mean of its assigned points. If a cluster is empty, keep its previous centroid.',
  '# ✏️ YOUR IMPLEMENTATION HERE

def kmeans(x: torch.Tensor, num_clusters: int, num_iters: int = 10) -> tuple[torch.Tensor, torch.Tensor]:
    # x: (num_points, dim)
    pass  # Replace this',
  '[{"name": "Output shapes", "code": "\nimport torch\nx = torch.tensor([\n    [0.0, 0.0],\n    [5.0, 5.0],\n    [0.2, -0.1],\n    [4.8, 5.2],\n], dtype=torch.float32)\ncentroids, assignments = {fn}(x, num_clusters=2, num_iters=4)\nassert centroids.shape == (2, 2), f''Centroid shape mismatch: {centroids.shape}''\nassert assignments.shape == (4,), f''Assignment shape mismatch: {assignments.shape}''\nassert assignments.dtype in (torch.int32, torch.int64), f''Assignments should be integer typed, got {assignments.dtype}''\n"}, {"name": "Finds two simple clusters", "code": "\nimport torch\nx = torch.tensor([\n    [0.0, 0.0],\n    [5.0, 5.0],\n    [0.0, 1.0],\n    [1.0, 0.0],\n    [5.0, 6.0],\n    [6.0, 5.0],\n], dtype=torch.float32)\ncentroids, assignments = {fn}(x, num_clusters=2, num_iters=10)\nexpected = torch.tensor([[1.0 / 3.0, 1.0 / 3.0], [16.0 / 3.0, 16.0 / 3.0]])\nassert torch.allclose(centroids, expected, atol=1e-4), f''Wrong centroids: {centroids} vs {expected}''\nassert torch.equal(assignments[[0, 2, 3]], torch.zeros(3, dtype=assignments.dtype)), f''First cluster assignments wrong: {assignments}''\nassert torch.equal(assignments[[1, 4, 5]], torch.ones(3, dtype=assignments.dtype)), f''Second cluster assignments wrong: {assignments}''\n"}, {"name": "Matches nearest-centroid rule after convergence", "code": "\nimport torch\nx = torch.tensor([\n    [0.0, 0.0],\n    [10.0, 10.0],\n    [0.2, 0.1],\n    [9.9, 10.2],\n    [0.1, -0.2],\n    [10.1, 9.8],\n], dtype=torch.float32)\ncentroids, assignments = {fn}(x, num_clusters=2, num_iters=8)\ndistances = torch.cdist(x, centroids)\nexpected_assignments = distances.argmin(dim=1)\nassert torch.equal(assignments, expected_assignments), ''Assignments are not the nearest centroids''\n"}, {"name": "Empty clusters keep previous centroid", "code": "\nimport torch\nx = torch.tensor([\n    [0.0, 0.0],\n    [10.0, 10.0],\n    [10.0, 10.0],\n    [10.0, 10.0],\n], dtype=torch.float32)\ncentroids, assignments = {fn}(x, num_clusters=3, num_iters=5)\nexpected = torch.tensor([\n    [0.0, 0.0],\n    [10.0, 10.0],\n    [10.0, 10.0],\n], dtype=torch.float32)\nassert torch.allclose(centroids, expected, atol=1e-5), f''Unexpected centroids with empty cluster: {centroids}''\nassert assignments.shape == (4,), ''Assignments shape changed unexpectedly''\n"}]',
  '# ✅ SOLUTION

def kmeans(x: torch.Tensor, num_clusters: int, num_iters: int = 10) -> tuple[torch.Tensor, torch.Tensor]:
    centroids = x[:num_clusters].clone()

    for _ in range(num_iters):
        distances = torch.cdist(x, centroids)
        assignments = distances.argmin(dim=1)

        new_centroids = centroids.clone()
        for cluster_idx in range(num_clusters):
            mask = assignments == cluster_idx
            if mask.any():
                new_centroids[cluster_idx] = x[mask].mean(dim=0)

        centroids = new_centroids

    distances = torch.cdist(x, centroids)
    assignments = distances.argmin(dim=1)
    return centroids, assignments',
  '# 🟡 Solution: K-Means Clustering',
  'approved',
  27
)
