INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'temperature_sampling',
  'Temperature Sampling',
  'Medium',
  'ML 基础与解码策略',
  'temperature_sample',
  '# 🟡 Medium: Temperature Sampling

Implement **temperature sampling** from logits.

Scale the logits by dividing by `temperature`, apply softmax, then sample a token.

### Signature
```python
def temperature_sample(logits: torch.Tensor, temperature: float) -> torch.Tensor:
    ...
```

### Rules
- Support both 1-D and batched logits
- Sample one token per row
- `temperature` must be positive

### Example
```
token_ids = temperature_sample(logits, temperature=0.8)
```',
  'def temperature_sample(logits: torch.Tensor, temperature: float) -> torch.Tensor:',
  'token_ids = temperature_sample(logits, temperature=0.8)',
  'Scale logits by dividing by temperature before softmax. Lower temperature makes the distribution sharper; higher temperature makes it flatter. Then sample with torch.multinomial.',
  '# ✏️ YOUR IMPLEMENTATION HERE

def temperature_sample(logits: torch.Tensor, temperature: float) -> torch.Tensor:
    pass  # Replace this',
  '[{"name": "Returns one token per row", "code": "\nimport torch\ntorch.manual_seed(0)\nlogits = torch.tensor([[1.0, 2.0, 3.0], [3.0, 2.0, 1.0]])\nout = {fn}(logits, temperature=0.7)\nassert out.shape == (2,), f''Expected one sample per row, got {out.shape}''\nassert out.dtype in (torch.int32, torch.int64), f''Output should be integer typed, got {out.dtype}''\n"}, {"name": "Matches reference sampling with fixed seed", "code": "\nimport torch\nlogits = torch.tensor([[2.0, 0.5, -1.0], [0.1, 0.2, 0.3]], dtype=torch.float32)\ntorch.manual_seed(42)\nout = {fn}(logits, temperature=0.8)\ntorch.manual_seed(42)\nprobs = torch.softmax(logits / 0.8, dim=-1)\nexpected = torch.multinomial(probs, num_samples=1).squeeze(-1)\nassert torch.equal(out, expected), f''Wrong sampled tokens: {out} vs {expected}''\n"}, {"name": "Very low temperature behaves greedily", "code": "\nimport torch\nlogits = torch.tensor([0.0, 5.0, 1.0], dtype=torch.float32)\ntorch.manual_seed(0)\nout = {fn}(logits, temperature=1e-4)\nassert out.item() == 1, f''Low temperature should almost always pick argmax, got {out.item()}''\n"}]',
  '# ✅ SOLUTION

def temperature_sample(logits: torch.Tensor, temperature: float) -> torch.Tensor:
    if temperature <= 0:
        raise ValueError("temperature must be positive")

    squeeze = logits.dim() == 1
    if squeeze:
        logits = logits.unsqueeze(0)

    probs = torch.softmax(logits / temperature, dim=-1)
    samples = torch.multinomial(probs, num_samples=1).squeeze(-1)
    return samples.squeeze(0) if squeeze else samples',
  '# 🟡 Solution: Temperature Sampling',
  'approved',
  28
)
