INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'top_k_sampling',
  'Top-k Sampling',
  'Medium',
  'ML 基础与解码策略',
  'top_k_sample',
  '# 🟡 Medium: Top-k Sampling

Implement **top-k sampling** for logits.

Keep only the top `k` logits, mask the rest out, and sample from the remaining distribution.

### Signature
```python
def top_k_sample(logits: torch.Tensor, k: int) -> torch.Tensor:
    ...
```

### Rules
- Support both 1-D and batched logits
- Return one sampled token per row
- `k=1` should behave like greedy decoding

### Example
```
token_ids = top_k_sample(logits, k=10)
```',
  'def top_k_sample(logits: torch.Tensor, k: int) -> torch.Tensor:',
  'token_ids = top_k_sample(logits, k=10)',
  'Find the top-k logits, mask all other logits to -inf, apply softmax over the remaining tokens, then sample from that truncated distribution.',
  '# ✏️ YOUR IMPLEMENTATION HERE

def top_k_sample(logits: torch.Tensor, k: int) -> torch.Tensor:
    pass  # Replace this',
  '[{"name": "Samples only from top-k tokens", "code": "\nimport torch\ntorch.manual_seed(0)\nlogits = torch.tensor([[5.0, 4.0, 1.0, -2.0]])\nout = {fn}(logits, k=2)\nassert out.item() in (0, 1), f''Sampled token must be in the top-2 set, got {out.item()}''\n"}, {"name": "Matches reference sampling with fixed seed", "code": "\nimport torch\nlogits = torch.tensor([[2.0, 1.5, 0.1, -1.0], [0.2, 3.0, 2.5, 0.0]], dtype=torch.float32)\ntorch.manual_seed(123)\nout = {fn}(logits, k=2)\n\ntorch.manual_seed(123)\ntop_values, top_indices = torch.topk(logits, k=2, dim=-1)\nmasked = torch.full_like(logits, float(''-inf''))\nmasked.scatter_(-1, top_indices, top_values)\nprobs = torch.softmax(masked, dim=-1)\nexpected = torch.multinomial(probs, num_samples=1).squeeze(-1)\nassert torch.equal(out, expected), f''Sampled tokens mismatch: {out} vs {expected}''\n"}, {"name": "k=1 equals greedy", "code": "\nimport torch\nlogits = torch.tensor([[0.2, 1.7, 0.8], [3.0, 2.0, 1.0]])\nout = {fn}(logits, k=1)\nexpected = logits.argmax(dim=-1)\nassert torch.equal(out, expected), f''k=1 should be greedy: {out} vs {expected}''\n"}]',
  '# ✅ SOLUTION

def top_k_sample(logits: torch.Tensor, k: int) -> torch.Tensor:
    squeeze = logits.dim() == 1
    if squeeze:
        logits = logits.unsqueeze(0)

    k = min(k, logits.shape[-1])
    top_values, top_indices = torch.topk(logits, k=k, dim=-1)
    masked = torch.full_like(logits, float("-inf"))
    masked.scatter_(-1, top_indices, top_values)
    probs = torch.softmax(masked, dim=-1)
    samples = torch.multinomial(probs, num_samples=1).squeeze(-1)
    return samples.squeeze(0) if squeeze else samples',
  '# 🟡 Solution: Top-k Sampling',
  'approved',
  29
)
