INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'beam_search',
  'Beam Search Decoding',
  'Hard',
  'ML 基础与解码策略',
  'beam_search_decode',
  '# 🔴 Hard: Beam Search Decoding

Implement a simplified **beam search decoder** over a matrix of log-probabilities.

Input shape: `(seq_len, vocab_size)`.
At each timestep, expand all current beams with every token, accumulate log-probabilities, and keep the top `beam_width` sequences.

### Signature
```python
def beam_search_decode(log_probs: torch.Tensor, beam_width: int) -> tuple[torch.Tensor, float]:
    ...
```

### Rules
- Return the best sequence and its total log-probability
- Sequence length must equal `seq_len`
- Use additive scores in log space

### Example
```
sequence, score = beam_search_decode(log_probs, beam_width=3)
```',
  'def beam_search_decode(log_probs: torch.Tensor, beam_width: int) -> tuple[torch.Tensor, float]:',
  'sequence, score = beam_search_decode(log_probs, beam_width=3)',
  'Keep a list of the top beam_width partial sequences. At each timestep, expand every beam with every token, add the current log-probability to the running score, then keep only the best beam_width candidates.',
  '# ✏️ YOUR IMPLEMENTATION HERE

def beam_search_decode(log_probs: torch.Tensor, beam_width: int) -> tuple[torch.Tensor, float]:
    pass  # Replace this',
  '[{"name": "Output types", "code": "\nimport torch\nlog_probs = torch.log(torch.tensor([\n    [0.6, 0.3, 0.1],\n    [0.2, 0.5, 0.3],\n], dtype=torch.float32))\nsequence, score = {fn}(log_probs, beam_width=2)\nassert isinstance(sequence, torch.Tensor), f''Sequence should be a tensor, got {type(sequence)}''\nassert sequence.shape == (2,), f''Sequence shape mismatch: {sequence.shape}''\nassert sequence.dtype in (torch.int32, torch.int64), f''Sequence should be integer typed, got {sequence.dtype}''\nassert isinstance(score, float), f''Score should be a Python float, got {type(score)}''\n"}, {"name": "Matches exhaustive search on tiny example", "code": "\nimport itertools\nimport torch\nlog_probs = torch.log(torch.tensor([\n    [0.50, 0.30, 0.20],\n    [0.10, 0.70, 0.20],\n    [0.60, 0.25, 0.15],\n], dtype=torch.float32))\nsequence, score = {fn}(log_probs, beam_width=2)\nbest_seq = None\nbest_score = None\nfor seq in itertools.product(range(3), repeat=3):\n    seq_score = sum(log_probs[t, token].item() for t, token in enumerate(seq))\n    if best_score is None or seq_score > best_score:\n        best_seq = seq\n        best_score = seq_score\nexpected_sequence = torch.tensor(best_seq)\nassert torch.equal(sequence, expected_sequence), f''Wrong sequence: {sequence} vs {expected_sequence}''\nassert abs(score - best_score) < 1e-6, f''Wrong score: {score} vs {best_score}''\n"}, {"name": "Beam width 1 equals greedy", "code": "\nimport torch\nlog_probs = torch.log(torch.tensor([\n    [0.1, 0.8, 0.1],\n    [0.7, 0.1, 0.2],\n    [0.2, 0.3, 0.5],\n], dtype=torch.float32))\nsequence, score = {fn}(log_probs, beam_width=1)\nexpected = torch.tensor([1, 0, 2])\nexpected_score = log_probs[0, 1].item() + log_probs[1, 0].item() + log_probs[2, 2].item()\nassert torch.equal(sequence, expected), f''Beam width 1 should be greedy: {sequence} vs {expected}''\nassert abs(score - expected_score) < 1e-6, ''Score mismatch for beam width 1''\n"}]',
  '# ✅ SOLUTION

def beam_search_decode(log_probs: torch.Tensor, beam_width: int) -> tuple[torch.Tensor, float]:
    beams = [([], 0.0)]
    seq_len, vocab_size = log_probs.shape

    for t in range(seq_len):
        candidates = []
        for sequence, score in beams:
            for token in range(vocab_size):
                candidates.append((sequence + [token], score + float(log_probs[t, token].item())))
        candidates.sort(key=lambda item: item[1], reverse=True)
        beams = candidates[:beam_width]

    best_sequence, best_score = beams[0]
    return torch.tensor(best_sequence, dtype=torch.long), best_score',
  '# 🔴 Solution: Beam Search Decoding',
  'approved',
  30
)
