INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'mlp_backward',
  'Hand-Written Backward for a 2-Layer MLP',
  'Hard',
  'ML 基础与解码策略',
  'mlp_backward',
  '# 🔴 Hard: Hand-Written Backward for a 2-Layer MLP

Implement the **manual backward pass** for a 2-layer MLP with ReLU activation and MSE loss.

Forward definition:
- `z1 = x @ w1.T + b1`
- `h = relu(z1)`
- `y = h @ w2.T + b2`
- `loss = mean((y - target)^2)`

### Signature
```python
def mlp_backward(x, w1, b1, w2, b2, target) -> dict[str, torch.Tensor]:
    ...
```

### Rules
- Do not call `backward()` inside your implementation
- Return gradients for `w1`, `b1`, `w2`, and `b2`
- Match PyTorch autograd numerically

### Example
```
grads = mlp_backward(x, w1, b1, w2, b2, target)
```',
  'def mlp_backward(x, w1, b1, w2, b2, target) -> dict[str, torch.Tensor]:',
  'grads = mlp_backward(x, w1, b1, w2, b2, target)',
  'Forward: z1 = x @ w1.T + b1, h = ReLU(z1), y = h @ w2.T + b2, loss = mean((y - target)^2). Backprop from the MSE loss manually, then multiply by the ReLU mask (z1 > 0).',
  '# ✏️ YOUR IMPLEMENTATION HERE

def mlp_backward(x, w1, b1, w2, b2, target) -> dict[str, torch.Tensor]:
    pass  # Replace this',
  '[{"name": "Returns all gradient tensors", "code": "\nimport torch\nx = torch.randn(4, 3)\nw1 = torch.randn(5, 3)\nb1 = torch.randn(5)\nw2 = torch.randn(2, 5)\nb2 = torch.randn(2)\ntarget = torch.randn(4, 2)\ngrads = {fn}(x, w1, b1, w2, b2, target)\nassert set(grads.keys()) == {''w1'', ''b1'', ''w2'', ''b2''}, f''Wrong gradient keys: {grads.keys()}''\nassert grads[''w1''].shape == w1.shape\nassert grads[''b1''].shape == b1.shape\nassert grads[''w2''].shape == w2.shape\nassert grads[''b2''].shape == b2.shape\n"}, {"name": "Matches autograd", "code": "\nimport torch\ntorch.manual_seed(0)\nx = torch.randn(6, 4)\nw1 = torch.randn(7, 4)\nb1 = torch.randn(7)\nw2 = torch.randn(3, 7)\nb2 = torch.randn(3)\ntarget = torch.randn(6, 3)\ngrads = {fn}(x, w1, b1, w2, b2, target)\n\nw1_ref = w1.clone().requires_grad_(True)\nb1_ref = b1.clone().requires_grad_(True)\nw2_ref = w2.clone().requires_grad_(True)\nb2_ref = b2.clone().requires_grad_(True)\n\nz1 = x @ w1_ref.T + b1_ref\nh = torch.relu(z1)\nout = h @ w2_ref.T + b2_ref\nloss = ((out - target) ** 2).mean()\nloss.backward()\n\nassert torch.allclose(grads[''w1''], w1_ref.grad, atol=1e-5), ''w1 gradient mismatch''\nassert torch.allclose(grads[''b1''], b1_ref.grad, atol=1e-5), ''b1 gradient mismatch''\nassert torch.allclose(grads[''w2''], w2_ref.grad, atol=1e-5), ''w2 gradient mismatch''\nassert torch.allclose(grads[''b2''], b2_ref.grad, atol=1e-5), ''b2 gradient mismatch''\n"}, {"name": "ReLU blocks negative hidden units", "code": "\nimport torch\nx = torch.tensor([[1.0, 1.0]])\nw1 = torch.tensor([[-2.0, -2.0], [1.0, 1.0]])\nb1 = torch.tensor([-1.0, 0.0])\nw2 = torch.tensor([[3.0, 4.0]])\nb2 = torch.tensor([0.0])\ntarget = torch.tensor([[1.0]])\ngrads = {fn}(x, w1, b1, w2, b2, target)\nassert torch.allclose(grads[''w1''][0], torch.zeros_like(grads[''w1''][0])), ''Negative ReLU unit should have zero weight gradient''\nassert torch.allclose(grads[''b1''][0], torch.tensor(0.0)), ''Negative ReLU unit should have zero bias gradient''\nassert grads[''w1''][1].abs().sum() > 0, ''Active ReLU unit should receive gradient''\n"}]',
  '# ✅ SOLUTION

def mlp_backward(x, w1, b1, w2, b2, target) -> dict[str, torch.Tensor]:
    z1 = x @ w1.T + b1
    h = torch.relu(z1)
    y = h @ w2.T + b2

    grad_y = 2.0 * (y - target) / y.numel()
    grad_w2 = grad_y.T @ h
    grad_b2 = grad_y.sum(dim=0)

    grad_h = grad_y @ w2
    grad_z1 = grad_h * (z1 > 0).to(z1.dtype)
    grad_w1 = grad_z1.T @ x
    grad_b1 = grad_z1.sum(dim=0)

    return {
        "w1": grad_w1,
        "b1": grad_b1,
        "w2": grad_w2,
        "b2": grad_b2,
    }',
  '# 🔴 Solution: Hand-Written Backward for a 2-Layer MLP',
  'approved',
  31
)
