INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'top_p_sampling',
  'Top-p Sampling',
  'Hard',
  'ML 基础与解码策略',
  'top_p_sample',
  '# 🔴 Hard: Top-p Sampling

Implement **top-p (nucleus) sampling**.

Sort tokens by probability, keep the smallest prefix whose cumulative probability reaches `p`, renormalize, then sample from that nucleus.

### Signature
```python
def top_p_sample(logits: torch.Tensor, p: float) -> torch.Tensor:
    ...
```

### Rules
- Support both 1-D and batched logits
- Always keep at least one token
- Sample one token per row

### Example
```
token_ids = top_p_sample(logits, p=0.9)
```',
  'def top_p_sample(logits: torch.Tensor, p: float) -> torch.Tensor:',
  'token_ids = top_p_sample(logits, p=0.9)',
  'Sort tokens by probability descending, take the smallest prefix whose cumulative probability reaches p, mask the rest, renormalize, and sample from that nucleus.',
  '# ✏️ YOUR IMPLEMENTATION HERE

def top_p_sample(logits: torch.Tensor, p: float) -> torch.Tensor:
    pass  # Replace this',
  '[{"name": "Samples only from nucleus set", "code": "\nimport torch\ntorch.manual_seed(0)\nlogits = torch.tensor([[4.0, 3.5, 1.0, -2.0]], dtype=torch.float32)\nout = {fn}(logits, p=0.8)\nassert out.item() in (0, 1), f''Sampled token must come from the nucleus set, got {out.item()}''\n"}, {"name": "Matches reference sampling with fixed seed", "code": "\nimport torch\n\ndef reference_top_p(logits: torch.Tensor, p: float) -> torch.Tensor:\n    if logits.dim() == 1:\n        logits = logits.unsqueeze(0)\n    probs = torch.softmax(logits, dim=-1)\n    outputs = []\n    for row in probs:\n        sorted_probs, sorted_indices = torch.sort(row, descending=True)\n        cumulative = sorted_probs.cumsum(dim=0)\n        keep = cumulative <= p\n        keep[0] = True\n        first_exceed = torch.nonzero(cumulative > p, as_tuple=False)\n        if first_exceed.numel() > 0:\n            keep[first_exceed[0, 0]] = True\n        filtered = torch.zeros_like(row)\n        filtered[sorted_indices[keep]] = row[sorted_indices[keep]]\n        filtered = filtered / filtered.sum()\n        token = torch.multinomial(filtered, num_samples=1)\n        outputs.append(token)\n    return torch.stack(outputs).squeeze(-1)\n\nlogits = torch.tensor([[2.5, 2.0, 1.0, -0.5], [0.1, 0.2, 3.0, 2.9]], dtype=torch.float32)\ntorch.manual_seed(9)\nout = {fn}(logits, p=0.75)\ntorch.manual_seed(9)\nexpected = reference_top_p(logits, p=0.75)\nassert torch.equal(out, expected), f''Sampled tokens mismatch: {out} vs {expected}''\n"}, {"name": "Small p still keeps at least one token", "code": "\nimport torch\nlogits = torch.tensor([1.0, 5.0, 0.5], dtype=torch.float32)\ntorch.manual_seed(0)\nout = {fn}(logits, p=0.01)\nassert out.item() == 1, f''At least the top token must remain available, got {out.item()}''\n"}]',
  '# ✅ SOLUTION

def top_p_sample(logits: torch.Tensor, p: float) -> torch.Tensor:
    squeeze = logits.dim() == 1
    if squeeze:
        logits = logits.unsqueeze(0)

    probs = torch.softmax(logits, dim=-1)
    outputs = []
    for row in probs:
        sorted_probs, sorted_indices = torch.sort(row, descending=True)
        cumulative = sorted_probs.cumsum(dim=0)
        keep = cumulative <= p
        keep[0] = True

        first_exceed = torch.nonzero(cumulative > p, as_tuple=False)
        if first_exceed.numel() > 0:
            keep[first_exceed[0, 0]] = True

        filtered = torch.zeros_like(row)
        filtered[sorted_indices[keep]] = row[sorted_indices[keep]]
        filtered = filtered / filtered.sum()
        outputs.append(torch.multinomial(filtered, num_samples=1).squeeze(0))

    outputs = torch.stack(outputs)
    return outputs.squeeze(0) if squeeze else outputs',
  '# 🔴 Solution: Top-p Sampling',
  'approved',
  33
)
