INSERT INTO problems (slug, title, difficulty, category, function_name, description, signature, example, hint, template_code, tests_json, solution_code, solution_markdown, status, sort_order)
VALUES (
  'dpo_loss',
  'DPO Loss',
  'Hard',
  'RLHF',
  'dpo_loss',
  '# 🔴 Hard: DPO Loss

Implement the **Direct Preference Optimization (DPO)** loss.

Use the policy preference gap relative to the reference model:
`beta * ((pi_chosen - pi_rejected) - (ref_chosen - ref_rejected))`

Then apply `-logsigmoid(...)` and average across the batch.

### Signature
```python
def dpo_loss(policy_chosen, policy_rejected, ref_chosen, ref_rejected, beta: float) -> torch.Tensor:
    ...
```

### Example
```
loss = dpo_loss(policy_chosen, policy_rejected, ref_chosen, ref_rejected, beta=0.1)
```',
  'def dpo_loss(policy_chosen, policy_rejected, ref_chosen, ref_rejected, beta: float) -> torch.Tensor:',
  'loss = dpo_loss(policy_chosen, policy_rejected, ref_chosen, ref_rejected, beta=0.1)',
  'DPO compares the policy preference gap against the reference preference gap. Compute logits = beta * ((pi_chosen - pi_rejected) - (ref_chosen - ref_rejected)), then return -logsigmoid(logits).mean().',
  '# ✏️ YOUR IMPLEMENTATION HERE

def dpo_loss(policy_chosen, policy_rejected, ref_chosen, ref_rejected, beta: float) -> torch.Tensor:
    pass  # Replace this',
