VALUES (
  'grpo_loss',
  'GRPO Loss',
  'Hard',
  'RLHF',
  'grpo_loss',
  '# 🔴 Hard: GRPO Loss

Implement a simplified **GRPO loss**.

First normalize rewards within each group:
`adv = (reward - mean(group)) / (std(group) + 1e-8)`

Then plug those group-relative advantages into the clipped PPO objective.

### Signature
```python
def grpo_loss(old_log_probs, new_log_probs, rewards, group_ids, clip_eps: float) -> torch.Tensor:
    ...
```

### Example
```
loss = grpo_loss(old_log_probs, new_log_probs, rewards, group_ids, clip_eps=0.2)
```',
  'def grpo_loss(old_log_probs, new_log_probs, rewards, group_ids, clip_eps: float) -> torch.Tensor:',
  'loss = grpo_loss(old_log_probs, new_log_probs, rewards, group_ids, clip_eps=0.2)',
  'First normalize rewards within each group to get group-relative advantages: (r - mean(group)) / (std(group) + eps). Then reuse the PPO clipped objective with ratio = exp(new_log_probs - old_log_probs).',
  '# ✏️ YOUR IMPLEMENTATION HERE

def grpo_loss(old_log_probs, new_log_probs, rewards, group_ids, clip_eps: float) -> torch.Tensor:
    pass  # Replace this',
  '[{"name": "Matches reference formula", "code": "\nimport torch\nold_log_probs = torch.log(torch.tensor([0.3, 0.4, 0.2, 0.5], dtype=torch.float32))\nnew_log_probs = torch.log(torch.tensor([0.33, 0.36, 0.25, 0.45], dtype=torch.float32))\nrewards = torch.tensor([1.0, 3.0, 2.0, 6.0], dtype=torch.float32)\ngroup_ids = torch.tensor([0, 0, 1, 1], dtype=torch.int64)\nloss = {fn}(old_log_probs, new_log_probs, rewards, group_ids, clip_eps=0.2)\n\nadvantages = torch.zeros_like(rewards)\nfor gid in torch.unique(group_ids):\n    mask = group_ids == gid\n    group_rewards = rewards[mask]\n    advantages[mask] = (group_rewards - group_rewards.mean()) / (group_rewards.std(unbiased=False) + 1e-8)\n\nratio = torch.exp(new_log_probs - old_log_probs)\nunclipped = ratio * advantages\nclipped = torch.clamp(ratio, 0.8, 1.2) * advantages\nexpected = -torch.minimum(unclipped, clipped).mean()\nassert torch.allclose(loss, expected, atol=1e-6), f''Loss mismatch: {loss} vs {expected}''\n"}, {"name": "Invariant to per-group reward shifts", "code": "\nimport torch\nold_log_probs = torch.log(torch.tensor([0.2, 0.4, 0.5, 0.1], dtype=torch.float32))\nnew_log_probs = torch.log(torch.tensor([0.25, 0.35, 0.45, 0.12], dtype=torch.float32))\nrewards = torch.tensor([1.0, 2.0, 10.0, 11.0], dtype=torch.float32)\nshifted = torch.tensor([101.0, 102.0, -5.0, -4.0], dtype=torch.float32)\ngroup_ids = torch.tensor([0, 0, 1, 1], dtype=torch.int64)\nloss_a = {fn}(old_log_probs, new_log_probs, rewards, group_ids, clip_eps=0.2)\nloss_b = {fn}(old_log_probs, new_log_probs, shifted, group_ids, clip_eps=0.2)\nassert torch.allclose(loss_a, loss_b, atol=1e-6), f''Per-group shifts should not change the loss: {loss_a} vs {loss_b}''\n"}, {"name": "Single-item groups have zero advantage", "code": "\nimport torch\nold_log_probs = torch.zeros(3)\nnew_log_probs = torch.tensor([0.1, -0.2, 0.3])\nrewards = torch.tensor([5.0, 6.0, 7.0])\ngroup_ids = torch.tensor([0, 1, 2], dtype=torch.int64)\nloss = {fn}(old_log_probs, new_log_probs, rewards, group_ids, clip_eps=0.2)\nassert torch.allclose(loss, torch.tensor(0.0), atol=1e-6), f''Single-item groups should produce zero normalized advantage, got {loss}''\n"}]',
  '# ✅ SOLUTION

def grpo_loss(old_log_probs, new_log_probs, rewards, group_ids, clip_eps: float) -> torch.Tensor:
    advantages = torch.zeros_like(rewards)
    for gid in torch.unique(group_ids):
        mask = group_ids == gid
        group_rewards = rewards[mask]
        advantages[mask] = (group_rewards - group_rewards.mean()) / (group_rewards.std(unbiased=False) + 1e-8)

    ratio = torch.exp(new_log_probs - old_log_probs)
    unclipped = ratio * advantages
    clipped = torch.clamp(ratio, 1.0 - clip_eps, 1.0 + clip_eps) * advantages
    return -torch.minimum(unclipped, clipped).mean()',
  '# 🔴 Solution: GRPO Loss',
  'approved',
  35
)
