VALUES (
  'ppo_loss',
  'PPO Clipped Policy Loss',
  'Hard',
  'RLHF',
  'ppo_clipped_loss',
  '# 🔴 Hard: PPO Clipped Policy Loss

Implement the **clipped PPO policy loss**.

Use:
- `ratio = exp(new_log_probs - old_log_probs)`
- `unclipped = ratio * advantages`
- `clipped = clamp(ratio, 1-eps, 1+eps) * advantages`
- `loss = -mean(min(unclipped, clipped))`

### Signature
```python
def ppo_clipped_loss(old_log_probs, new_log_probs, advantages, clip_eps: float) -> torch.Tensor:
    ...
```

### Example
```
loss = ppo_clipped_loss(old_log_probs, new_log_probs, advantages, clip_eps=0.2)
```',
  'def ppo_clipped_loss(old_log_probs, new_log_probs, advantages, clip_eps: float) -> torch.Tensor:',
  'loss = ppo_clipped_loss(old_log_probs, new_log_probs, advantages, clip_eps=0.2)',
  'Compute ratio = exp(new_log_probs - old_log_probs). Then form the unclipped objective ratio * advantages and the clipped one clamp(ratio, 1-eps, 1+eps) * advantages. PPO uses the minimum of the two, and the loss is the negative mean.',
  '# ✏️ YOUR IMPLEMENTATION HERE

def ppo_clipped_loss(old_log_probs, new_log_probs, advantages, clip_eps: float) -> torch.Tensor:
    pass  # Replace this',
  '[{"name": "Matches reference formula", "code": "\nimport torch\nold_log_probs = torch.log(torch.tensor([0.2, 0.5, 0.3], dtype=torch.float32))\nnew_log_probs = torch.log(torch.tensor([0.25, 0.45, 0.30], dtype=torch.float32))\nadvantages = torch.tensor([1.0, -0.5, 2.0], dtype=torch.float32)\nloss = {fn}(old_log_probs, new_log_probs, advantages, clip_eps=0.2)\nratio = torch.exp(new_log_probs - old_log_probs)\nunclipped = ratio * advantages\nclipped = torch.clamp(ratio, 0.8, 1.2) * advantages\nexpected = -torch.minimum(unclipped, clipped).mean()\nassert torch.allclose(loss, expected, atol=1e-6), f''Loss mismatch: {loss} vs {expected}''\n"}, {"name": "Positive advantages are clipped when ratio is too large", "code": "\nimport torch\nold_log_probs = torch.zeros(3)\nnew_log_probs = torch.log(torch.tensor([2.0, 2.5, 3.0]))\nadvantages = torch.ones(3)\nloss = {fn}(old_log_probs, new_log_probs, advantages, clip_eps=0.1)\nexpected = -torch.tensor(1.1)\nassert torch.allclose(loss, expected, atol=1e-6), f''Expected clipped objective mean -1.1, got {loss}''\n"}, {"name": "Negative advantages use clipped lower ratio", "code": "\nimport torch\nold_log_probs = torch.zeros(2)\nnew_log_probs = torch.log(torch.tensor([0.2, 0.5]))\nadvantages = torch.tensor([-1.0, -2.0])\nloss = {fn}(old_log_probs, new_log_probs, advantages, clip_eps=0.1)\nratio = torch.exp(new_log_probs - old_log_probs)\nunclipped = ratio * advantages\nclipped = torch.clamp(ratio, 0.9, 1.1) * advantages\nexpected = -torch.minimum(unclipped, clipped).mean()\nassert torch.allclose(loss, expected, atol=1e-6), ''Negative-advantage clipping mismatch''\n"}]',
  '# ✅ SOLUTION

def ppo_clipped_loss(old_log_probs, new_log_probs, advantages, clip_eps: float) -> torch.Tensor:
    ratio = torch.exp(new_log_probs - old_log_probs)
    unclipped = ratio * advantages
    clipped = torch.clamp(ratio, 1.0 - clip_eps, 1.0 + clip_eps) * advantages
    return -torch.minimum(unclipped, clipped).mean()',
  '# 🔴 Solution: PPO Clipped Policy Loss',
  'approved',
  36
)
